INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('3-4-sit-up', '3/4 Sit-Up', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', '3_4_Sit-Up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie down on the floor and secure your feet. Your legs should be bent at the knees.' FROM exercise WHERE slug = '3-4-sit-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.' FROM exercise WHERE slug = '3-4-sit-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Flex your hips and spine to raise your torso toward your knees.' FROM exercise WHERE slug = '3-4-sit-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.' FROM exercise WHERE slug = '3-4-sit-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = '3-4-sit-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = '3-4-sit-up' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = '3-4-sit-up' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = '3-4-sit-up';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('90-90-hamstring', '90/90 Hamstring', 'stretching', 'push', NULL, 'beginner', 0, 15, 'free-exercise-db', '90_90_Hamstring', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on your back, with one leg extended straight out.' FROM exercise WHERE slug = '90-90-hamstring';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.' FROM exercise WHERE slug = '90-90-hamstring';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.' FROM exercise WHERE slug = '90-90-hamstring';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for 10-20 repetitions, and then switch to the other leg.' FROM exercise WHERE slug = '90-90-hamstring';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = '90-90-hamstring' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = '90-90-hamstring' AND b.slug = 'calves';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = '90-90-hamstring' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = '90-90-hamstring';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('ab-crunch-machine', 'Ab Crunch Machine', 'strength', 'pull', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Ab_Crunch_Machine', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.' FROM exercise WHERE slug = 'ab-crunch-machine';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.' FROM exercise WHERE slug = 'ab-crunch-machine';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After a second pause, slowly return to the starting position as you breathe in.' FROM exercise WHERE slug = 'ab-crunch-machine';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the movement for the prescribed amount of repetitions.' FROM exercise WHERE slug = 'ab-crunch-machine';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'ab-crunch-machine' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'ab-crunch-machine' AND q.slug = 'machine';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'ab-crunch-machine';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'ab-crunch-machine';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('ab-roller', 'Ab Roller', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Ab_Roller', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold the Ab Roller with both hands and kneel on the floor.' FROM exercise WHERE slug = 'ab-roller';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.' FROM exercise WHERE slug = 'ab-roller';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.' FROM exercise WHERE slug = 'ab-roller';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.' FROM exercise WHERE slug = 'ab-roller';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'ab-roller' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'ab-roller' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'ab-roller' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'ab-roller';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('adductor', 'Adductor', 'stretching', 'static', 'isolation', 'intermediate', 0, 15, 'free-exercise-db', 'Adductor', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie face down with one leg on a foam roll.' FROM exercise WHERE slug = 'adductor';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.' FROM exercise WHERE slug = 'adductor';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.' FROM exercise WHERE slug = 'adductor';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'adductor' AND b.slug = 'adductors';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'adductor' AND q.slug = 'foam-roll';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'adductor';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('adductor-groin', 'Adductor/Groin', 'stretching', 'static', NULL, 'intermediate', 0, 15, 'free-exercise-db', 'Adductor_Groin', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on your back with your feet raised towards the ceiling.' FROM exercise WHERE slug = 'adductor-groin';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.' FROM exercise WHERE slug = 'adductor-groin';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.' FROM exercise WHERE slug = 'adductor-groin';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.' FROM exercise WHERE slug = 'adductor-groin';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'adductor-groin' AND b.slug = 'adductors';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'adductor-groin';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('advanced-kettlebell-windmill', 'Advanced Kettlebell Windmill', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Advanced_Kettlebell_Windmill', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Clean and press a kettlebell overhead with one arm.' FROM exercise WHERE slug = 'advanced-kettlebell-windmill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.' FROM exercise WHERE slug = 'advanced-kettlebell-windmill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower yourself as far as possible.' FROM exercise WHERE slug = 'advanced-kettlebell-windmill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pause for a second and reverse the motion back to the starting position.' FROM exercise WHERE slug = 'advanced-kettlebell-windmill';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'advanced-kettlebell-windmill' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'advanced-kettlebell-windmill' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'advanced-kettlebell-windmill' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'advanced-kettlebell-windmill' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'advanced-kettlebell-windmill' AND q.slug = 'kettlebells';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'advanced-kettlebell-windmill';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'advanced-kettlebell-windmill';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('air-bike', 'Air Bike', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Air_Bike', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.' FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.' FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.' FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Go back to the initial position as you breathe in.' FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.' FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.' FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'air-bike' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'air-bike' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'air-bike';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('all-fours-quad-stretch', 'All Fours Quad Stretch', 'stretching', 'static', NULL, 'intermediate', 0, 15, 'free-exercise-db', 'All_Fours_Quad_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.' FROM exercise WHERE slug = 'all-fours-quad-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.' FROM exercise WHERE slug = 'all-fours-quad-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.' FROM exercise WHERE slug = 'all-fours-quad-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'all-fours-quad-stretch' AND b.slug = 'quadriceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'all-fours-quad-stretch' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'all-fours-quad-stretch';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('alternate-hammer-curl', 'Alternate Hammer Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Alternate_Hammer_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.' FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'The palms of the hands should be facing your torso. This will be your starting position.' FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.' FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Slowly begin to bring the dumbbells back to starting position as your breathe in.' FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat the movement with the left hand. This equals one repetition.' FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Continue alternating in this manner for the recommended amount of repetitions.' FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'alternate-hammer-curl' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'alternate-hammer-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'alternate-hammer-curl' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'alternate-hammer-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('alternate-heel-touchers', 'Alternate Heel Touchers', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Alternate_Heel_Touchers', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.' FROM exercise WHERE slug = 'alternate-heel-touchers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.' FROM exercise WHERE slug = 'alternate-heel-touchers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now go back slowly to the starting position as you inhale.' FROM exercise WHERE slug = 'alternate-heel-touchers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.' FROM exercise WHERE slug = 'alternate-heel-touchers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Continue alternating sides in this manner until all prescribed repetitions are done.' FROM exercise WHERE slug = 'alternate-heel-touchers';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'alternate-heel-touchers' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'alternate-heel-touchers' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'alternate-heel-touchers';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('alternate-incline-dumbbell-curl', 'Alternate Incline Dumbbell Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Alternate_Incline_Dumbbell_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.' FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.' FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly begin to bring the dumbbell back to starting position as your breathe in.' FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the movement with the left hand. This equals one repetition.' FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Continue alternating in this manner for the recommended amount of repetitions.' FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'alternate-incline-dumbbell-curl' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'alternate-incline-dumbbell-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'alternate-incline-dumbbell-curl' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'alternate-incline-dumbbell-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('alternate-leg-diagonal-bound', 'Alternate Leg Diagonal Bound', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Alternate_Leg_Diagonal_Bound', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Assume a comfortable stance with one foot slightly in front of the other.' FROM exercise WHERE slug = 'alternate-leg-diagonal-bound';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.' FROM exercise WHERE slug = 'alternate-leg-diagonal-bound';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'It may help to use a line on the ground to guage distance from side to side.' FROM exercise WHERE slug = 'alternate-leg-diagonal-bound';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the sequence with the other leg.' FROM exercise WHERE slug = 'alternate-leg-diagonal-bound';
