INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('alternating-cable-shoulder-press', 'Alternating Cable Shoulder Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Alternating_Cable_Shoulder_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Move the cables to the bottom of the tower and select an appropriate weight.' FROM exercise WHERE slug = 'alternating-cable-shoulder-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.' FROM exercise WHERE slug = 'alternating-cable-shoulder-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Keeping your head and chest up, extend through the elbow to press one side directly over head.' FROM exercise WHERE slug = 'alternating-cable-shoulder-press';
