INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'In a standing position, hold a pair of dumbbells at your side.' FROM exercise WHERE slug = 'alternating-deltoid-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.' FROM exercise WHERE slug = 'alternating-deltoid-raise';
