INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on the floor with two kettlebells next to your shoulders.' FROM exercise WHERE slug = 'alternating-floor-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.' FROM exercise WHERE slug = 'alternating-floor-press';
