INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('alternating-hang-clean', 'Alternating Hang Clean', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Alternating_Hang_Clean', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.' FROM exercise WHERE slug = 'alternating-hang-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.' FROM exercise WHERE slug = 'alternating-hang-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.' FROM exercise WHERE slug = 'alternating-hang-clean';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'alternating-hang-clean' AND b.slug = 'hamstrings';
