INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('ankle-circles', 'Ankle Circles', 'stretching', 'pull', 'isolation', 'beginner', 0, 15, 'free-exercise-db', 'Ankle_Circles', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Use a sturdy object like a squat rack to hold yourself.' FROM exercise WHERE slug = 'ankle-circles';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.' FROM exercise WHERE slug = 'ankle-circles';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'When you are done with the right foot, then repeat with the left leg.' FROM exercise WHERE slug = 'ankle-circles';
