INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('ankle-on-the-knee', 'Ankle On The Knee', 'stretching', 'static', NULL, 'beginner', 0, 15, 'free-exercise-db', 'Ankle_On_The_Knee', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'From a lying position, bend your knees and keep your feet on the floor.' FROM exercise WHERE slug = 'ankle-on-the-knee';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your ankle of one foot on your opposite knee.' FROM exercise WHERE slug = 'ankle-on-the-knee';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.' FROM exercise WHERE slug = 'ankle-on-the-knee';
