INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('anterior-tibialis-smr', 'Anterior Tibialis-SMR', 'stretching', 'static', NULL, 'intermediate', 0, 15, 'free-exercise-db', 'Anterior_Tibialis-SMR', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin seated on the ground with your legs bent and your feet on the floor.' FROM exercise WHERE slug = 'anterior-tibialis-smr';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.' FROM exercise WHERE slug = 'anterior-tibialis-smr';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'anterior-tibialis-smr' AND b.slug = 'calves';
