INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('atlas-stones', 'Atlas Stones', 'strongman', 'pull', 'compound', 'expert', 60, 120, 'free-exercise-db', 'Atlas_Stones', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.' FROM exercise WHERE slug = 'atlas-stones';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.' FROM exercise WHERE slug = 'atlas-stones';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.' FROM exercise WHERE slug = 'atlas-stones';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.' FROM exercise WHERE slug = 'atlas-stones';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'atlas-stones' AND b.slug = 'lower-back';
