INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('backward-medicine-ball-throw', 'Backward Medicine Ball Throw', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Backward_Medicine_Ball_Throw', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.' FROM exercise WHERE slug = 'backward-medicine-ball-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.' FROM exercise WHERE slug = 'backward-medicine-ball-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.' FROM exercise WHERE slug = 'backward-medicine-ball-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.' FROM exercise WHERE slug = 'backward-medicine-ball-throw';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'backward-medicine-ball-throw' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'backward-medicine-ball-throw' AND q.slug = 'medicine-ball';
