INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('balance-board', 'Balance Board', 'strength', NULL, 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Balance_Board', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place a balance board in front of you.' FROM exercise WHERE slug = 'balance-board';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand up on it and try to balance yourself.' FROM exercise WHERE slug = 'balance-board';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Hold the balance for as long as desired.' FROM exercise WHERE slug = 'balance-board';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'balance-board' AND b.slug = 'calves';
