INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('ball-leg-curl', 'Ball Leg Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Ball_Leg_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin on the floor laying on your back with your feet on top of the ball.' FROM exercise WHERE slug = 'ball-leg-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.' FROM exercise WHERE slug = 'ball-leg-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.' FROM exercise WHERE slug = 'ball-leg-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.' FROM exercise WHERE slug = 'ball-leg-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After a brief pause, return to the starting position.' FROM exercise WHERE slug = 'ball-leg-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'ball-leg-curl' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'ball-leg-curl' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'ball-leg-curl' AND b.slug = 'glutes';
