INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'ball-leg-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('band-assisted-pull-up', 'Band Assisted Pull-Up', 'strength', NULL, 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Band_Assisted_Pull-Up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.' FROM exercise WHERE slug = 'band-assisted-pull-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.' FROM exercise WHERE slug = 'band-assisted-pull-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.' FROM exercise WHERE slug = 'band-assisted-pull-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After a brief pause, return to the starting position.' FROM exercise WHERE slug = 'band-assisted-pull-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'band-assisted-pull-up' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-assisted-pull-up' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-assisted-pull-up' AND b.slug = 'forearms';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-assisted-pull-up' AND b.slug = 'middle-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'band-assisted-pull-up' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'band-assisted-pull-up';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('band-good-morning', 'Band Good Morning', 'powerlifting', 'pull', 'compound', 'beginner', 60, 150, 'free-exercise-db', 'Band_Good_Morning', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.' FROM exercise WHERE slug = 'band-good-morning';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Keeping your legs straight, extend through the hips to come to a near vertical position.' FROM exercise WHERE slug = 'band-good-morning';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Ensure that you do not round your back as you go down back to the starting position.' FROM exercise WHERE slug = 'band-good-morning';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'band-good-morning' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-good-morning' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-good-morning' AND b.slug = 'lower-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'band-good-morning' AND q.slug = 'bands';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'band-good-morning';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('band-good-morning-pull-through', 'Band Good Morning (Pull Through)', 'powerlifting', 'pull', 'compound', 'beginner', 60, 150, 'free-exercise-db', 'Band_Good_Morning_Pull_Through', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.' FROM exercise WHERE slug = 'band-good-morning-pull-through';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.' FROM exercise WHERE slug = 'band-good-morning-pull-through';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Return to the starting position be driving through with the hips to come back to a standing position.' FROM exercise WHERE slug = 'band-good-morning-pull-through';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'band-good-morning-pull-through' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-good-morning-pull-through' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-good-morning-pull-through' AND b.slug = 'lower-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'band-good-morning-pull-through' AND q.slug = 'bands';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'band-good-morning-pull-through';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('band-hip-adductions', 'Band Hip Adductions', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Band_Hip_Adductions', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Anchor a band around a solid post or other object.' FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.' FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Stand up straight and hold onto the post if needed. This will be your starting position.' FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Keeping the knee straight, raise your right legs out to the side as far as you can.' FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Return to the starting position and repeat for the desired rep count.' FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Switch sides.' FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'band-hip-adductions' AND b.slug = 'adductors';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'band-hip-adductions' AND q.slug = 'bands';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'band-hip-adductions';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('band-pull-apart', 'Band Pull Apart', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Band_Pull_Apart', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin with your arms extended straight out in front of you, holding the band with both hands.' FROM exercise WHERE slug = 'band-pull-apart';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.' FROM exercise WHERE slug = 'band-pull-apart';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.' FROM exercise WHERE slug = 'band-pull-apart';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pause as you complete the movement, returning to the starting position under control.' FROM exercise WHERE slug = 'band-pull-apart';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'band-pull-apart' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-pull-apart' AND b.slug = 'middle-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'band-pull-apart' AND b.slug = 'traps';
