INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'band-pull-apart';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('band-skull-crusher', 'Band Skull Crusher', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Band_Skull_Crusher', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.' FROM exercise WHERE slug = 'band-skull-crusher';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.' FROM exercise WHERE slug = 'band-skull-crusher';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.' FROM exercise WHERE slug = 'band-skull-crusher';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'band-skull-crusher' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'band-skull-crusher' AND q.slug = 'bands';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'band-skull-crusher';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-ab-rollout', 'Barbell Ab Rollout', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Barbell_Ab_Rollout', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.' FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.' FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.' FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-ab-rollout' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-ab-rollout' AND b.slug = 'lower-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-ab-rollout' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-ab-rollout' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-ab-rollout-on-knees', 'Barbell Ab Rollout - On Knees', 'strength', 'pull', 'compound', 'expert', 30, 90, 'free-exercise-db', 'Barbell_Ab_Rollout_-_On_Knees', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.' FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.' FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.' FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.' FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-ab-rollout-on-knees' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-ab-rollout-on-knees' AND b.slug = 'lower-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-ab-rollout-on-knees' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-ab-rollout-on-knees' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-bench-press-medium-grip', 'Barbell Bench Press - Medium Grip', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Barbell_Bench_Press_-_Medium_Grip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.' FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.' FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.' FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the movement for the prescribed amount of repetitions.' FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'When you are done, place the bar back in the rack.' FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-bench-press-medium-grip' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-bench-press-medium-grip' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-bench-press-medium-grip' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-bench-press-medium-grip' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-curl', 'Barbell Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Barbell_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.' FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.' FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.' FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Slowly begin to bring the bar back to starting position as your breathe in.' FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-curl' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-curl' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-curls-lying-against-an-incline', 'Barbell Curls Lying Against An Incline', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Barbell_Curls_Lying_Against_An_Incline', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.' FROM exercise WHERE slug = 'barbell-curls-lying-against-an-incline';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.' FROM exercise WHERE slug = 'barbell-curls-lying-against-an-incline';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.' FROM exercise WHERE slug = 'barbell-curls-lying-against-an-incline';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'barbell-curls-lying-against-an-incline';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-curls-lying-against-an-incline' AND b.slug = 'biceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-curls-lying-against-an-incline' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'barbell-curls-lying-against-an-incline';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-curls-lying-against-an-incline';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-deadlift', 'Barbell Deadlift', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Barbell_Deadlift', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand in front of a loaded barbell.' FROM exercise WHERE slug = 'barbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.' FROM exercise WHERE slug = 'barbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.' FROM exercise WHERE slug = 'barbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.' FROM exercise WHERE slug = 'barbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Perform the amount of repetitions prescribed in the program.' FROM exercise WHERE slug = 'barbell-deadlift';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'lower-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'forearms';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'middle-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'barbell-deadlift' AND b.slug = 'traps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-deadlift' AND q.slug = 'barbell';
