INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-hack-squat';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-hip-thrust', 'Barbell Hip Thrust', 'powerlifting', 'push', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Barbell_Hip_Thrust', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.' FROM exercise WHERE slug = 'barbell-hip-thrust';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.' FROM exercise WHERE slug = 'barbell-hip-thrust';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.' FROM exercise WHERE slug = 'barbell-hip-thrust';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-hip-thrust' AND b.slug = 'glutes';
