INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-incline-shoulder-raise', 'Barbell Incline Shoulder Raise', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Barbell_Incline_Shoulder_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.' FROM exercise WHERE slug = 'barbell-incline-shoulder-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.' FROM exercise WHERE slug = 'barbell-incline-shoulder-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Bring back the bar to the starting position as you breathe in.' FROM exercise WHERE slug = 'barbell-incline-shoulder-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'barbell-incline-shoulder-raise';
