INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'barbell-rollout-from-bench';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('barbell-seated-calf-raise', 'Barbell Seated Calf Raise', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Barbell_Seated_Calf_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place a block about 12 inches in front of a flat bench.' FROM exercise WHERE slug = 'barbell-seated-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Sit on the bench and place the ball of your feet on the block.' FROM exercise WHERE slug = 'barbell-seated-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.' FROM exercise WHERE slug = 'barbell-seated-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.' FROM exercise WHERE slug = 'barbell-seated-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.' FROM exercise WHERE slug = 'barbell-seated-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'barbell-seated-calf-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'barbell-seated-calf-raise' AND b.slug = 'calves';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'barbell-seated-calf-raise' AND q.slug = 'barbell';
