INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.' FROM exercise WHERE slug = 'bent-over-two-dumbbell-row-with-palms-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.' FROM exercise WHERE slug = 'bent-over-two-dumbbell-row-with-palms-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly lower the weight again to the starting position as you inhale.' FROM exercise WHERE slug = 'bent-over-two-dumbbell-row-with-palms-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'bent-over-two-dumbbell-row-with-palms-in';
