INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'bent-over-two-dumbbell-row-with-palms-in' AND b.slug = 'lats';
