INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bicycling-stationary', 'Bicycling, Stationary', 'cardio', NULL, NULL, 'beginner', 15, 60, 'free-exercise-db', 'Bicycling_Stationary', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, seat yourself on the bike and adjust the seat to your height.' FROM exercise WHERE slug = 'bicycling-stationary';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.' FROM exercise WHERE slug = 'bicycling-stationary';
