INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('body-tricep-press', 'Body Tricep Press', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Body_Tricep_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a bar in a rack at chest height.' FROM exercise WHERE slug = 'body-tricep-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.' FROM exercise WHERE slug = 'body-tricep-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin by flexing the elbow, lowering yourself towards the bar.' FROM exercise WHERE slug = 'body-tricep-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pause, and then reverse the motion by extending the elbows.' FROM exercise WHERE slug = 'body-tricep-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Progress from bodyweight by adding chains over your shoulders.' FROM exercise WHERE slug = 'body-tricep-press';
