INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bodyweight-flyes', 'Bodyweight Flyes', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Bodyweight_Flyes', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.' FROM exercise WHERE slug = 'bodyweight-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.' FROM exercise WHERE slug = 'bodyweight-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Place your hands on the bars. This will be your starting position.' FROM exercise WHERE slug = 'bodyweight-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.' FROM exercise WHERE slug = 'bodyweight-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.' FROM exercise WHERE slug = 'bodyweight-flyes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'bodyweight-flyes' AND b.slug = 'chest';
