INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bodyweight-mid-row', 'Bodyweight Mid Row', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Bodyweight_Mid_Row', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.' FROM exercise WHERE slug = 'bodyweight-mid-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.' FROM exercise WHERE slug = 'bodyweight-mid-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After a brief pause, return to the starting position.' FROM exercise WHERE slug = 'bodyweight-mid-row';
