INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bodyweight-squat', 'Bodyweight Squat', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Bodyweight_Squat', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.' FROM exercise WHERE slug = 'bodyweight-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin the movement by flexing your knees and hips, sitting back with your hips.' FROM exercise WHERE slug = 'bodyweight-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.' FROM exercise WHERE slug = 'bodyweight-squat';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'bodyweight-squat' AND b.slug = 'quadriceps';
