INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bodyweight-walking-lunge', 'Bodyweight Walking Lunge', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Bodyweight_Walking_Lunge', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin standing with your feet shoulder width apart and your hands on your hips.' FROM exercise WHERE slug = 'bodyweight-walking-lunge';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.' FROM exercise WHERE slug = 'bodyweight-walking-lunge';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.' FROM exercise WHERE slug = 'bodyweight-walking-lunge';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Step forward with your rear foot, repeating the lunge on the opposite leg.' FROM exercise WHERE slug = 'bodyweight-walking-lunge';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'bodyweight-walking-lunge' AND b.slug = 'quadriceps';
