INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bosu-ball-cable-crunch-with-side-bends', 'Bosu Ball Cable Crunch With Side Bends', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Bosu_Ball_Cable_Crunch_With_Side_Bends', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Connect a standard handle to each arm of a cable machine, and position them in the most downward position.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Grab a Bosu Ball and position it in front and center of the cable machine.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'With both hands, reach back and grab the handle of each cable.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'Repeat the same series of movements to failure.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 9, 'Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 10, 'Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.' FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'bosu-ball-cable-crunch-with-side-bends' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'bosu-ball-cable-crunch-with-side-bends' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'bosu-ball-cable-crunch-with-side-bends';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bottoms-up-clean-from-the-hang-position', 'Bottoms-Up Clean From The Hang Position', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Bottoms-Up_Clean_From_The_Hang_Position', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Initiate the exercise by standing upright with a kettlebell in one hand.' FROM exercise WHERE slug = 'bottoms-up-clean-from-the-hang-position';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.' FROM exercise WHERE slug = 'bottoms-up-clean-from-the-hang-position';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'bottoms-up-clean-from-the-hang-position' AND b.slug = 'forearms';
