INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('bottoms-up', 'Bottoms Up', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Bottoms_Up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.' FROM exercise WHERE slug = 'bottoms-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.' FROM exercise WHERE slug = 'bottoms-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After a brief pause, return to the starting position.' FROM exercise WHERE slug = 'bottoms-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'bottoms-up' AND b.slug = 'abdominals';
