INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'bottoms-up';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('box-jump-multiple-response', 'Box Jump (Multiple Response)', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Box_Jump_Multiple_Response', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.' FROM exercise WHERE slug = 'box-jump-multiple-response';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.' FROM exercise WHERE slug = 'box-jump-multiple-response';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Immediately drop or jump back down to the original starting place; then repeat the sequence.' FROM exercise WHERE slug = 'box-jump-multiple-response';
