INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('box-skip', 'Box Skip', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Box_Skip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'You will need several boxes lined up about 8 feet apart.' FROM exercise WHERE slug = 'box-skip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin facing the first box with one leg slightly behind the other.' FROM exercise WHERE slug = 'box-skip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Drive off the back leg, attempting to gain as much height with the hips as possible.' FROM exercise WHERE slug = 'box-skip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.' FROM exercise WHERE slug = 'box-skip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Then, step to the next box and repeat.' FROM exercise WHERE slug = 'box-skip';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'box-skip' AND b.slug = 'hamstrings';
