INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('cat-stretch', 'Cat Stretch', 'stretching', 'static', NULL, 'beginner', 0, 15, 'free-exercise-db', 'Cat_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position yourself on the floor on your hands and knees.' FROM exercise WHERE slug = 'cat-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.' FROM exercise WHERE slug = 'cat-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Hold for 15 seconds.' FROM exercise WHERE slug = 'cat-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'cat-stretch' AND b.slug = 'lower-back';
