INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'chair-leg-extended-stretch' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'chair-leg-extended-stretch';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('chair-lower-back-stretch', 'Chair Lower Back Stretch', 'stretching', 'static', 'isolation', 'beginner', 0, 15, 'free-exercise-db', 'Chair_Lower_Back_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Sit upright on a chair.' FROM exercise WHERE slug = 'chair-lower-back-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Bend to one side with your arm over your head. You can hold onto the chair with your free hand.' FROM exercise WHERE slug = 'chair-lower-back-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Hold for 10 seconds, and repeat for your other side.' FROM exercise WHERE slug = 'chair-lower-back-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'chair-lower-back-stretch' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'chair-lower-back-stretch' AND b.slug = 'lower-back';
