INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('clean-deadlift', 'Clean Deadlift', 'olympic_weightlifting', 'pull', 'compound', 'beginner', 60, 120, 'free-exercise-db', 'Clean_Deadlift', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.' FROM exercise WHERE slug = 'clean-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.' FROM exercise WHERE slug = 'clean-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.' FROM exercise WHERE slug = 'clean-deadlift';
