INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('clean-and-press', 'Clean and Press', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Clean_and_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Stand to full height, holding the bar in the clean position.' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Without moving your feet, press the bar overhead as you exhale. Lower the bar under control .' FROM exercise WHERE slug = 'clean-and-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'clean-and-press' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'clean-and-press' AND b.slug = 'abdominals';
