INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('clean-from-blocks', 'Clean from Blocks', 'olympic_weightlifting', 'pull', 'compound', 'intermediate', 60, 120, 'free-exercise-db', 'Clean_from_Blocks', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.' FROM exercise WHERE slug = 'clean-from-blocks';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.' FROM exercise WHERE slug = 'clean-from-blocks';
