INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('double-kettlebell-jerk', 'Double Kettlebell Jerk', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Double_Kettlebell_Jerk', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold a kettlebell by the handle in each hand.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Dip your body by bending the knees, keeping your torso upright.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Return your feet to the ground in a split fashion, with one foot forward and one foot back.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition.' FROM exercise WHERE slug = 'double-kettlebell-jerk';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'double-kettlebell-jerk' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'double-kettlebell-jerk' AND b.slug = 'calves';
