INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('double-kettlebell-push-press', 'Double Kettlebell Push Press', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Double_Kettlebell_Push_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Clean two kettlebells to your shoulders.' FROM exercise WHERE slug = 'double-kettlebell-push-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.' FROM exercise WHERE slug = 'double-kettlebell-push-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.' FROM exercise WHERE slug = 'double-kettlebell-push-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'double-kettlebell-push-press' AND b.slug = 'shoulders';
