INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('double-kettlebell-snatch', 'Double Kettlebell Snatch', 'strength', 'pull', 'compound', 'expert', 30, 90, 'free-exercise-db', 'Double_Kettlebell_Snatch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.' FROM exercise WHERE slug = 'double-kettlebell-snatch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Swing the kettlebells between your legs forcefully and reverse the direction.' FROM exercise WHERE slug = 'double-kettlebell-snatch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.' FROM exercise WHERE slug = 'double-kettlebell-snatch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'double-kettlebell-snatch' AND b.slug = 'shoulders';
