INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('double-leg-butt-kick', 'Double Leg Butt Kick', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Double_Leg_Butt_Kick', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin standing with your knees slightly bent.' FROM exercise WHERE slug = 'double-leg-butt-kick';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.' FROM exercise WHERE slug = 'double-leg-butt-kick';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.' FROM exercise WHERE slug = 'double-leg-butt-kick';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.' FROM exercise WHERE slug = 'double-leg-butt-kick';
