INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.' FROM exercise WHERE slug = 'downward-facing-balance';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'downward-facing-balance' AND b.slug = 'glutes';
