INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('drop-push', 'Drop Push', 'plyometrics', 'push', 'compound', 'intermediate', 30, 60, 'free-exercise-db', 'Drop_Push', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position low boxes or other platforms 2-3 feet apart.' FROM exercise WHERE slug = 'drop-push';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Move to a pushup position between them, supporting yourself by placing your hands on the boxes.' FROM exercise WHERE slug = 'drop-push';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.' FROM exercise WHERE slug = 'drop-push';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'drop-push' AND b.slug = 'chest';
