INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('dumbbell-alternate-bicep-curl', 'Dumbbell Alternate Bicep Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Dumbbell_Alternate_Bicep_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.' FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.' FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.' FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the movement with the left hand. This equals one repetition.' FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Continue alternating in this manner for the recommended amount of repetitions.' FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-alternate-bicep-curl' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-alternate-bicep-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'dumbbell-alternate-bicep-curl' AND q.slug = 'dumbbell';
