INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('dumbbell-seated-box-jump', 'Dumbbell Seated Box Jump', 'plyometrics', 'push', 'compound', 'intermediate', 30, 60, 'free-exercise-db', 'Dumbbell_Seated_Box_Jump', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.' FROM exercise WHERE slug = 'dumbbell-seated-box-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.' FROM exercise WHERE slug = 'dumbbell-seated-box-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.' FROM exercise WHERE slug = 'dumbbell-seated-box-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Step down and return to the starting position.' FROM exercise WHERE slug = 'dumbbell-seated-box-jump';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-seated-box-jump' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-seated-box-jump' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-seated-box-jump' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-seated-box-jump' AND b.slug = 'hamstrings';
