INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('dumbbell-seated-one-leg-calf-raise', 'Dumbbell Seated One-Leg Calf Raise', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Dumbbell_Seated_One-Leg_Calf_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place a block on the floor about 12 inches from a flat bench.' FROM exercise WHERE slug = 'dumbbell-seated-one-leg-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.' FROM exercise WHERE slug = 'dumbbell-seated-one-leg-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now place the ball of your left foot on the block. This will be your starting position.' FROM exercise WHERE slug = 'dumbbell-seated-one-leg-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.' FROM exercise WHERE slug = 'dumbbell-seated-one-leg-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Slowly return to the starting position, stretching as far down as possible.' FROM exercise WHERE slug = 'dumbbell-seated-one-leg-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for your prescribed number of repetitions and then repeat with the right leg.' FROM exercise WHERE slug = 'dumbbell-seated-one-leg-calf-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-seated-one-leg-calf-raise' AND b.slug = 'calves';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'dumbbell-seated-one-leg-calf-raise' AND q.slug = 'dumbbell';
