INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'dumbbell-step-ups';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('dumbbell-tricep-extension-pronated-grip', 'Dumbbell Tricep Extension -Pronated Grip', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Dumbbell_Tricep_Extension_-Pronated_Grip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.' FROM exercise WHERE slug = 'dumbbell-tricep-extension-pronated-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.' FROM exercise WHERE slug = 'dumbbell-tricep-extension-pronated-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.' FROM exercise WHERE slug = 'dumbbell-tricep-extension-pronated-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Then, exhale and use your triceps to return the weight to the starting position.' FROM exercise WHERE slug = 'dumbbell-tricep-extension-pronated-grip';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'dumbbell-tricep-extension-pronated-grip' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'dumbbell-tricep-extension-pronated-grip' AND q.slug = 'dumbbell';
