INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('fast-skipping', 'Fast Skipping', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Fast_Skipping', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start in a relaxed position with one leg slightly forward. This will be your starting position.' FROM exercise WHERE slug = 'fast-skipping';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.' FROM exercise WHERE slug = 'fast-skipping';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.' FROM exercise WHERE slug = 'fast-skipping';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'fast-skipping' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'fast-skipping' AND b.slug = 'abductors';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'fast-skipping' AND b.slug = 'adductors';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'fast-skipping' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'fast-skipping' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'fast-skipping' AND b.slug = 'hamstrings';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'fast-skipping' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'fast-skipping';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('finger-curls', 'Finger Curls', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Finger_Curls', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.' FROM exercise WHERE slug = 'finger-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.' FROM exercise WHERE slug = 'finger-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.' FROM exercise WHERE slug = 'finger-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.' FROM exercise WHERE slug = 'finger-curls';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'finger-curls' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'finger-curls' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'finger-curls';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'finger-curls';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('flat-bench-cable-flyes', 'Flat Bench Cable Flyes', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Flat_Bench_Cable_Flyes', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Lay flat on the bench and keep your feet on the ground.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Slowly come back to the starting position.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'flat-bench-cable-flyes' AND b.slug = 'chest';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'flat-bench-cable-flyes' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('flat-bench-leg-pull-in', 'Flat Bench Leg Pull-In', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Flat_Bench_Leg_Pull-In', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on an exercise mat or a flat bench with your legs off the end.' FROM exercise WHERE slug = 'flat-bench-leg-pull-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.' FROM exercise WHERE slug = 'flat-bench-leg-pull-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.' FROM exercise WHERE slug = 'flat-bench-leg-pull-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'As you breathe in, slowly return to the starting position.' FROM exercise WHERE slug = 'flat-bench-leg-pull-in';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'flat-bench-leg-pull-in';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'flat-bench-leg-pull-in' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'flat-bench-leg-pull-in' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'flat-bench-leg-pull-in';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('flat-bench-lying-leg-raise', 'Flat Bench Lying Leg Raise', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Flat_Bench_Lying_Leg_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie with your back flat on a bench and your legs extended in front of you off the end.' FROM exercise WHERE slug = 'flat-bench-lying-leg-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.' FROM exercise WHERE slug = 'flat-bench-lying-leg-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.' FROM exercise WHERE slug = 'flat-bench-lying-leg-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now, as you inhale, slowly lower your legs back down to the starting position.' FROM exercise WHERE slug = 'flat-bench-lying-leg-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'flat-bench-lying-leg-raise' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'flat-bench-lying-leg-raise' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'flat-bench-lying-leg-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('flexor-incline-dumbbell-curls', 'Flexor Incline Dumbbell Curls', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Flexor_Incline_Dumbbell_Curls', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.' FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.' FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.' FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.' FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'As you inhale, slowly go back to the starting position.' FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'flexor-incline-dumbbell-curls' AND b.slug = 'biceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'flexor-incline-dumbbell-curls' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'flexor-incline-dumbbell-curls';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('floor-glute-ham-raise', 'Floor Glute-Ham Raise', 'strength', 'pull', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Floor_Glute-Ham_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'You can use a partner for this exercise or brace your feet under something stable.' FROM exercise WHERE slug = 'floor-glute-ham-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.' FROM exercise WHERE slug = 'floor-glute-ham-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.' FROM exercise WHERE slug = 'floor-glute-ham-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.' FROM exercise WHERE slug = 'floor-glute-ham-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'floor-glute-ham-raise' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'floor-glute-ham-raise' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'floor-glute-ham-raise' AND b.slug = 'glutes';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'floor-glute-ham-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('floor-press', 'Floor Press', 'powerlifting', 'push', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Floor_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.' FROM exercise WHERE slug = 'floor-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.' FROM exercise WHERE slug = 'floor-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.' FROM exercise WHERE slug = 'floor-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'floor-press' AND b.slug = 'triceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'floor-press' AND b.slug = 'chest';
