INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-cable-raise', 'Front Cable Raise', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Front_Cable_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.' FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.' FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.' FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now as you inhale lower the arm back down slowly to the starting position.' FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.' FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-cable-raise' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-cable-raise' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-cable-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-cone-hops-or-hurdle-hops', 'Front Cone Hops (or hurdle hops)', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Front_Cone_Hops_or_hurdle_hops', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Set up a row of cones or other small barriers, placing them a few feet apart.' FROM exercise WHERE slug = 'front-cone-hops-or-hurdle-hops';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.' FROM exercise WHERE slug = 'front-cone-hops-or-hurdle-hops';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin by jumping with both feet over the first cone, swinging both arms as you jump.' FROM exercise WHERE slug = 'front-cone-hops-or-hurdle-hops';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.' FROM exercise WHERE slug = 'front-cone-hops-or-hurdle-hops';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Continue until you have jumped over all of the cones.' FROM exercise WHERE slug = 'front-cone-hops-or-hurdle-hops';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-cone-hops-or-hurdle-hops' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-cone-hops-or-hurdle-hops' AND b.slug = 'abductors';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-cone-hops-or-hurdle-hops' AND b.slug = 'adductors';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-cone-hops-or-hurdle-hops' AND b.slug = 'calves';
