INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-dumbbell-raise', 'Front Dumbbell Raise', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Front_Dumbbell_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.' FROM exercise WHERE slug = 'front-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.' FROM exercise WHERE slug = 'front-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.' FROM exercise WHERE slug = 'front-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.' FROM exercise WHERE slug = 'front-dumbbell-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-dumbbell-raise' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-dumbbell-raise' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-dumbbell-raise';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-dumbbell-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-incline-dumbbell-raise', 'Front Incline Dumbbell Raise', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Front_Incline_Dumbbell_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.' FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.' FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.' FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Lower the arms back to the starting position as you inhale.' FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-incline-dumbbell-raise' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-incline-dumbbell-raise' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-incline-dumbbell-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-leg-raises', 'Front Leg Raises', 'stretching', 'pull', NULL, 'beginner', 0, 15, 'free-exercise-db', 'Front_Leg_Raises', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand next to a chair or other support, holding on with one hand.' FROM exercise WHERE slug = 'front-leg-raises';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.' FROM exercise WHERE slug = 'front-leg-raises';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-leg-raises' AND b.slug = 'hamstrings';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-leg-raises' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'front-leg-raises';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-plate-raise', 'Front Plate Raise', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Front_Plate_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.' FROM exercise WHERE slug = 'front-plate-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.' FROM exercise WHERE slug = 'front-plate-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you inhale, slowly lower the plate back down to the starting position.' FROM exercise WHERE slug = 'front-plate-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'front-plate-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-plate-raise' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-plate-raise' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-plate-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-raise-and-pullover', 'Front Raise And Pullover', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Front_Raise_And_Pullover', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.' FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.' FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.' FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now return the barbell to the starting position by reversing the motion as you exhale.' FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-raise-and-pullover' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-raise-and-pullover' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-raise-and-pullover' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-raise-and-pullover' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-raise-and-pullover' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-raise-and-pullover';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-squat-clean-grip', 'Front Squat (Clean Grip)', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Front_Squat_Clean_Grip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.' FROM exercise WHERE slug = 'front-squat-clean-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.' FROM exercise WHERE slug = 'front-squat-clean-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.' FROM exercise WHERE slug = 'front-squat-clean-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.' FROM exercise WHERE slug = 'front-squat-clean-grip';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-squat-clean-grip' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-squat-clean-grip' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-squat-clean-grip' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-squat-clean-grip' AND b.slug = 'hamstrings';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-squat-clean-grip' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-squat-clean-grip';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-squat-clean-grip';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-squats-with-two-kettlebells', 'Front Squats With Two Kettlebells', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Front_Squats_With_Two_Kettlebells', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.' FROM exercise WHERE slug = 'front-squats-with-two-kettlebells';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.' FROM exercise WHERE slug = 'front-squats-with-two-kettlebells';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Rise back up by driving through your heels and repeat.' FROM exercise WHERE slug = 'front-squats-with-two-kettlebells';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-squats-with-two-kettlebells' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-squats-with-two-kettlebells' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'front-squats-with-two-kettlebells' AND b.slug = 'glutes';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-squats-with-two-kettlebells' AND q.slug = 'kettlebells';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-squats-with-two-kettlebells';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-squats-with-two-kettlebells';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('front-two-dumbbell-raise', 'Front Two-Dumbbell Raise', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Front_Two-Dumbbell_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.' FROM exercise WHERE slug = 'front-two-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.' FROM exercise WHERE slug = 'front-two-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you inhale, lower the dumbbells back down slowly to the starting position.' FROM exercise WHERE slug = 'front-two-dumbbell-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'front-two-dumbbell-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'front-two-dumbbell-raise' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'front-two-dumbbell-raise' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'front-two-dumbbell-raise';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'front-two-dumbbell-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('full-range-of-motion-lat-pulldown', 'Full Range-Of-Motion Lat Pulldown', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Full_Range-Of-Motion_Lat_Pulldown', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.' FROM exercise WHERE slug = 'full-range-of-motion-lat-pulldown';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.' FROM exercise WHERE slug = 'full-range-of-motion-lat-pulldown';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'full-range-of-motion-lat-pulldown' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'full-range-of-motion-lat-pulldown' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'full-range-of-motion-lat-pulldown' AND b.slug = 'middle-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'full-range-of-motion-lat-pulldown' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'full-range-of-motion-lat-pulldown' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'full-range-of-motion-lat-pulldown';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'full-range-of-motion-lat-pulldown';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('gironda-sternum-chins', 'Gironda Sternum Chins', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Gironda_Sternum_Chins', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grasp the pull-up bar with a shoulder width underhand grip.' FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.' FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.' FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.' FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Slowly start going back to the starting position as you inhale.' FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'gironda-sternum-chins' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'gironda-sternum-chins' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'gironda-sternum-chins' AND b.slug = 'middle-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'gironda-sternum-chins' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'gironda-sternum-chins';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('glute-ham-raise', 'Glute Ham Raise', 'powerlifting', 'pull', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Glute_Ham_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.' FROM exercise WHERE slug = 'glute-ham-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.' FROM exercise WHERE slug = 'glute-ham-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Return to the starting position, keeping your descent under control.' FROM exercise WHERE slug = 'glute-ham-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'glute-ham-raise' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'glute-ham-raise' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'glute-ham-raise' AND b.slug = 'glutes';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'glute-ham-raise' AND q.slug = 'machine';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'glute-ham-raise';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'glute-ham-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('glute-kickback', 'Glute Kickback', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Glute_Kickback', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.' FROM exercise WHERE slug = 'glute-kickback';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.' FROM exercise WHERE slug = 'glute-kickback';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Go back to the initial position as you inhale and now repeat with the left leg.' FROM exercise WHERE slug = 'glute-kickback';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Continue to alternate legs until all of the recommended repetitions have been performed.' FROM exercise WHERE slug = 'glute-kickback';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'glute-kickback' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'glute-kickback' AND b.slug = 'hamstrings';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'glute-kickback' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'glute-kickback';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('goblet-squat', 'Goblet Squat', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Goblet_Squat', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.' FROM exercise WHERE slug = 'goblet-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.' FROM exercise WHERE slug = 'goblet-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.' FROM exercise WHERE slug = 'goblet-squat';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'goblet-squat' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'goblet-squat' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'goblet-squat' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'goblet-squat' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'goblet-squat' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'goblet-squat' AND q.slug = 'kettlebells';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'goblet-squat';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'goblet-squat';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('good-morning', 'Good Morning', 'powerlifting', 'push', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Good_Morning', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.' FROM exercise WHERE slug = 'good-morning';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.' FROM exercise WHERE slug = 'good-morning';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.' FROM exercise WHERE slug = 'good-morning';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'good-morning' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'good-morning' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'good-morning' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'good-morning' AND b.slug = 'lower-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'good-morning' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'good-morning';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'good-morning';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('good-morning-off-pins', 'Good Morning off Pins', 'powerlifting', 'push', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Good_Morning_off_Pins', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.' FROM exercise WHERE slug = 'good-morning-off-pins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.' FROM exercise WHERE slug = 'good-morning-off-pins';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'good-morning-off-pins' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'good-morning-off-pins' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'good-morning-off-pins' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'good-morning-off-pins' AND b.slug = 'lower-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'good-morning-off-pins' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'good-morning-off-pins';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'good-morning-off-pins';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('gorilla-chin-crunch', 'Gorilla Chin/Crunch', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Gorilla_Chin_Crunch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.' FROM exercise WHERE slug = 'gorilla-chin-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.' FROM exercise WHERE slug = 'gorilla-chin-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.' FROM exercise WHERE slug = 'gorilla-chin-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Slowly start to inhale as you return to the starting position.' FROM exercise WHERE slug = 'gorilla-chin-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'gorilla-chin-crunch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'gorilla-chin-crunch' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'gorilla-chin-crunch' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'gorilla-chin-crunch' AND b.slug = 'lats';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'gorilla-chin-crunch' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'gorilla-chin-crunch';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('groin-and-back-stretch', 'Groin and Back Stretch', 'stretching', 'static', 'compound', 'intermediate', 0, 15, 'free-exercise-db', 'Groin_and_Back_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Sit on the floor with your knees bent and feet together.' FROM exercise WHERE slug = 'groin-and-back-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Interlock your fingers behind your head. This will be your starting position.' FROM exercise WHERE slug = 'groin-and-back-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions.' FROM exercise WHERE slug = 'groin-and-back-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'groin-and-back-stretch' AND b.slug = 'adductors';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'groin-and-back-stretch';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('groiners', 'Groiners', 'stretching', 'pull', 'compound', 'intermediate', 0, 15, 'free-exercise-db', 'Groiners', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin in a pushup position on the floor. This will be your starting position.' FROM exercise WHERE slug = 'groiners';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.' FROM exercise WHERE slug = 'groiners';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.' FROM exercise WHERE slug = 'groiners';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'groiners' AND b.slug = 'adductors';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'groiners' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'groiners';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('hack-squat', 'Hack Squat', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Hack_Squat', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'hack-squat';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'hack-squat' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'hack-squat' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'hack-squat' AND b.slug = 'glutes';
