INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('hang-snatch-below-knees', 'Hang Snatch - Below Knees', 'olympic_weightlifting', 'pull', 'compound', 'expert', 60, 120, 'free-exercise-db', 'Hang_Snatch_-_Below_Knees', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.' FROM exercise WHERE slug = 'hang-snatch-below-knees';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.' FROM exercise WHERE slug = 'hang-snatch-below-knees';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.' FROM exercise WHERE slug = 'hang-snatch-below-knees';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return to a standing position with the weight overhead, and then return the weight to the floor under control.' FROM exercise WHERE slug = 'hang-snatch-below-knees';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'hang-snatch-below-knees' AND b.slug = 'hamstrings';
