INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.' FROM exercise WHERE slug = 'incline-dumbbell-flyes-with-a-twist';
