INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('incline-dumbbell-press', 'Incline Dumbbell Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Incline_Dumbbell_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat the movement for the prescribed amount of repetitions.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.' FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'incline-dumbbell-press' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'incline-dumbbell-press' AND b.slug = 'shoulders';
