INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('incline-push-up-close-grip', 'Incline Push-Up Close-Grip', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Incline_Push-Up_Close-Grip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.' FROM exercise WHERE slug = 'incline-push-up-close-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your hands next to one another on the bar.' FROM exercise WHERE slug = 'incline-push-up-close-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Position your feet back from the bar with arms and body straight. This will be your starting position.' FROM exercise WHERE slug = 'incline-push-up-close-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Keeping your body straight, lower your chest to the bar by bending the arms.' FROM exercise WHERE slug = 'incline-push-up-close-grip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Return to the starting position by extending the elbows, pressing yourself back up.' FROM exercise WHERE slug = 'incline-push-up-close-grip';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'incline-push-up-close-grip' AND b.slug = 'triceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'incline-push-up-close-grip' AND b.slug = 'chest';
