INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('incline-push-up-depth-jump', 'Incline Push-Up Depth Jump', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Incline_Push-Up_Depth_Jump', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.' FROM exercise WHERE slug = 'incline-push-up-depth-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.' FROM exercise WHERE slug = 'incline-push-up-depth-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.' FROM exercise WHERE slug = 'incline-push-up-depth-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the motion to return to the starting position.' FROM exercise WHERE slug = 'incline-push-up-depth-jump';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'incline-push-up-depth-jump' AND b.slug = 'chest';
