INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'incline-push-up-depth-jump' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'incline-push-up-depth-jump';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('incline-push-up-medium', 'Incline Push-Up Medium', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Incline_Push-Up_Medium', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.' FROM exercise WHERE slug = 'incline-push-up-medium';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your hands on the bar, with your hands about shoulder width apart.' FROM exercise WHERE slug = 'incline-push-up-medium';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Position your feet back from the bar with arms and body straight. This will be your starting position.' FROM exercise WHERE slug = 'incline-push-up-medium';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Keeping your body straight, lower your chest to the bar by bending the arms.' FROM exercise WHERE slug = 'incline-push-up-medium';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Return to the starting position by extending the elbows, pressing yourself back up.' FROM exercise WHERE slug = 'incline-push-up-medium';
