INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('incline-push-up-reverse-grip', 'Incline Push-Up Reverse Grip', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Incline_Push-Up_Reverse_Grip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.' FROM exercise WHERE slug = 'incline-push-up-reverse-grip';
