INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie face down on the floor, with a rope, belt, or band looped around one foot.' FROM exercise WHERE slug = 'intermediate-hip-flexor-and-quad-stretch';
