INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('internal-rotation-with-band', 'Internal Rotation with Band', 'strength', NULL, 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Internal_Rotation_with_Band', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.' FROM exercise WHERE slug = 'internal-rotation-with-band';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.' FROM exercise WHERE slug = 'internal-rotation-with-band';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.' FROM exercise WHERE slug = 'internal-rotation-with-band';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.' FROM exercise WHERE slug = 'internal-rotation-with-band';
