INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.' FROM exercise WHERE slug = 'inverted-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.' FROM exercise WHERE slug = 'inverted-row';
