INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.' FROM exercise WHERE slug = 'iron-crosses-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.' FROM exercise WHERE slug = 'iron-crosses-stretch';
