INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('isometric-neck-exercise-front-and-back', 'Isometric Neck Exercise - Front And Back', 'strength', 'static', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Isometric_Neck_Exercise_-_Front_And_Back', 'published');
