INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.' FROM exercise WHERE slug = 'isometric-neck-exercise-front-and-back';
