INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('kettlebell-figure-8', 'Kettlebell Figure 8', 'strength', 'pull', NULL, 'intermediate', 30, 90, 'free-exercise-db', 'Kettlebell_Figure_8', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.' FROM exercise WHERE slug = 'kettlebell-figure-8';
