INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('kipping-muscle-up', 'Kipping Muscle Up', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Kipping_Muscle_Up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grip the rings using a false grip, with the base of your palms on top of the rings.' FROM exercise WHERE slug = 'kipping-muscle-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin with a movement swinging your legs backward slightly.' FROM exercise WHERE slug = 'kipping-muscle-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.' FROM exercise WHERE slug = 'kipping-muscle-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Maintaining control and stability, extend through the elbow to complete the motion.' FROM exercise WHERE slug = 'kipping-muscle-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Use care when lowering yourself to the ground.' FROM exercise WHERE slug = 'kipping-muscle-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'kipping-muscle-up' AND b.slug = 'lats';
