INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('knee-circles', 'Knee Circles', 'stretching', 'pull', 'compound', 'beginner', 0, 15, 'free-exercise-db', 'Knee_Circles', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand with your legs together and hands by your waist.' FROM exercise WHERE slug = 'knee-circles';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now move your knees in a circular motion as you breathe normally.' FROM exercise WHERE slug = 'knee-circles';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'knee-circles';
