INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('kneeling-arm-drill', 'Kneeling Arm Drill', 'plyometrics', 'pull', NULL, 'beginner', 30, 60, 'free-exercise-db', 'Kneeling_Arm_Drill', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.' FROM exercise WHERE slug = 'kneeling-arm-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.' FROM exercise WHERE slug = 'kneeling-arm-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.' FROM exercise WHERE slug = 'kneeling-arm-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Switch knees and repeat.' FROM exercise WHERE slug = 'kneeling-arm-drill';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'kneeling-arm-drill' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'kneeling-arm-drill' AND b.slug = 'abdominals';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'kneeling-arm-drill';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('kneeling-cable-crunch-with-alternating-oblique-twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Grab the rope with both hands and kneel approximately two feet back from the tower.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Position the rope behind your head with your hands by your ears.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'Repeat the same movement as before, but alternate the other elbow to the opposite knee.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 9, 'Continue this series of movements to failure.' FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'kneeling-cable-crunch-with-alternating-oblique-twists' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'kneeling-cable-crunch-with-alternating-oblique-twists' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'kneeling-cable-crunch-with-alternating-oblique-twists';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('kneeling-cable-triceps-extension', 'Kneeling Cable Triceps Extension', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Kneeling_Cable_Triceps_Extension', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place a bench sideways in front of a high pulley machine.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Face away from the machine and kneel.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Slowly return to the starting position as you breathe in.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'kneeling-cable-triceps-extension' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'kneeling-cable-triceps-extension' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'kneeling-cable-triceps-extension';
