INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('leverage-high-row', 'Leverage High Row', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Leverage_High_Row', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.' FROM exercise WHERE slug = 'leverage-high-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.' FROM exercise WHERE slug = 'leverage-high-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pause at the bottom of the motion, and then slowly return the handles to the starting position.' FROM exercise WHERE slug = 'leverage-high-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.' FROM exercise WHERE slug = 'leverage-high-row';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'leverage-high-row' AND b.slug = 'middle-back';
