INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('leverage-iso-row', 'Leverage Iso Row', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Leverage_Iso_Row', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.' FROM exercise WHERE slug = 'leverage-iso-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.' FROM exercise WHERE slug = 'leverage-iso-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.' FROM exercise WHERE slug = 'leverage-iso-row';
