INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'leverage-shoulder-press';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('leverage-shrug', 'Leverage Shrug', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Leverage_Shrug', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Load the pins to an appropriate weight. Position yourself directly between the handles.' FROM exercise WHERE slug = 'leverage-shrug';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.' FROM exercise WHERE slug = 'leverage-shrug';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.' FROM exercise WHERE slug = 'leverage-shrug';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.' FROM exercise WHERE slug = 'leverage-shrug';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Pause at the top of the motion, and then return the weight to the starting position.' FROM exercise WHERE slug = 'leverage-shrug';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'leverage-shrug' AND b.slug = 'traps';
