INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('linear-3-part-start-technique', 'Linear 3-Part Start Technique', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Linear_3-Part_Start_Technique', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.' FROM exercise WHERE slug = 'linear-3-part-start-technique';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your right hand onto the line, and thing bring your nose close to your left knee.' FROM exercise WHERE slug = 'linear-3-part-start-technique';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.' FROM exercise WHERE slug = 'linear-3-part-start-technique';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.' FROM exercise WHERE slug = 'linear-3-part-start-technique';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'linear-3-part-start-technique' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'linear-3-part-start-technique' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'linear-3-part-start-technique' AND b.slug = 'quadriceps';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'linear-3-part-start-technique';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('linear-acceleration-wall-drill', 'Linear Acceleration Wall Drill', 'plyometrics', NULL, 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Linear_Acceleration_Wall_Drill', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.' FROM exercise WHERE slug = 'linear-acceleration-wall-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.' FROM exercise WHERE slug = 'linear-acceleration-wall-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Switch legs, raising the opposite knee, and then attacking the ground straight down.' FROM exercise WHERE slug = 'linear-acceleration-wall-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.' FROM exercise WHERE slug = 'linear-acceleration-wall-drill';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'linear-acceleration-wall-drill' AND b.slug = 'hamstrings';
