INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('linear-depth-jump', 'Linear Depth Jump', 'plyometrics', 'push', 'compound', 'intermediate', 30, 60, 'free-exercise-db', 'Linear_Depth_Jump', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.' FROM exercise WHERE slug = 'linear-depth-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.' FROM exercise WHERE slug = 'linear-depth-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.' FROM exercise WHERE slug = 'linear-depth-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Land softly, asborbing the impact through the legs.' FROM exercise WHERE slug = 'linear-depth-jump';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'linear-depth-jump' AND b.slug = 'quadriceps';
