INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('looking-at-ceiling', 'Looking At Ceiling', 'stretching', 'static', 'isolation', 'beginner', 0, 15, 'free-exercise-db', 'Looking_At_Ceiling', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Kneel on the floor, holding your heels with both hands.' FROM exercise WHERE slug = 'looking-at-ceiling';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.' FROM exercise WHERE slug = 'looking-at-ceiling';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'looking-at-ceiling' AND b.slug = 'quadriceps';
