INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('low-cable-crossover', 'Low Cable Crossover', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Low_Cable_Crossover', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.' FROM exercise WHERE slug = 'low-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.' FROM exercise WHERE slug = 'low-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.' FROM exercise WHERE slug = 'low-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return your arms back to the starting position after a brief pause.' FROM exercise WHERE slug = 'low-cable-crossover';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'low-cable-crossover' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'low-cable-crossover' AND b.slug = 'shoulders';
