INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('one-arm-kettlebell-split-jerk', 'One-Arm Kettlebell Split Jerk', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'One-Arm_Kettlebell_Split_Jerk', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Dip your body by bending the knees, keeping your torso upright.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-jerk';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-jerk';
