INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('one-arm-kettlebell-split-snatch', 'One-Arm Kettlebell Split Snatch', 'strength', 'pull', 'compound', 'expert', 30, 90, 'free-exercise-db', 'One-Arm_Kettlebell_Split_Snatch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold a kettlebell in one hand by the handle.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-snatch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-snatch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-snatch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.' FROM exercise WHERE slug = 'one-arm-kettlebell-split-snatch';
