INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.' FROM exercise WHERE slug = 'one-arm-long-bar-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.' FROM exercise WHERE slug = 'one-arm-long-bar-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.' FROM exercise WHERE slug = 'one-arm-long-bar-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.' FROM exercise WHERE slug = 'one-arm-long-bar-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After a brief pause, return to the starting position.' FROM exercise WHERE slug = 'one-arm-long-bar-row';
