INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('one-arm-medicine-ball-slam', 'One-Arm Medicine Ball Slam', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'One-Arm_Medicine_Ball_Slam', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.' FROM exercise WHERE slug = 'one-arm-medicine-ball-slam';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.' FROM exercise WHERE slug = 'one-arm-medicine-ball-slam';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.' FROM exercise WHERE slug = 'one-arm-medicine-ball-slam';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Catch the ball on the bounce and continue for the desired number of repetitions.' FROM exercise WHERE slug = 'one-arm-medicine-ball-slam';
