INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Throw the kettlebell out in front of you and catch the handle with one hand.' FROM exercise WHERE slug = 'one-arm-open-palm-kettlebell-clean';
