INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('one-arm-overhead-kettlebell-squats', 'One-Arm Overhead Kettlebell Squats', 'strength', 'push', 'compound', 'expert', 30, 90, 'free-exercise-db', 'One-Arm_Overhead_Kettlebell_Squats', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.' FROM exercise WHERE slug = 'one-arm-overhead-kettlebell-squats';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.' FROM exercise WHERE slug = 'one-arm-overhead-kettlebell-squats';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet.' FROM exercise WHERE slug = 'one-arm-overhead-kettlebell-squats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'one-arm-overhead-kettlebell-squats' AND b.slug = 'quadriceps';
