INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('otis-up', 'Otis-Up', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Otis-Up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.' FROM exercise WHERE slug = 'otis-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Initiate the movement by flexing the hips and spine to raise your torso up from the ground.' FROM exercise WHERE slug = 'otis-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you move up, press the weight up so that it is above your head at the top of the movement.' FROM exercise WHERE slug = 'otis-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.' FROM exercise WHERE slug = 'otis-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'otis-up' AND b.slug = 'abdominals';
