INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('pallof-press', 'Pallof Press', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Pallof_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.' FROM exercise WHERE slug = 'pallof-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.' FROM exercise WHERE slug = 'pallof-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.' FROM exercise WHERE slug = 'pallof-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.' FROM exercise WHERE slug = 'pallof-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Hold the repetition for several seconds before returning to the starting position.' FROM exercise WHERE slug = 'pallof-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'At the conclusion of the set, repeat facing the other direction.' FROM exercise WHERE slug = 'pallof-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'pallof-press' AND b.slug = 'abdominals';
