INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('pallof-press-with-rotation', 'Pallof Press With Rotation', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Pallof_Press_With_Rotation', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Connect a standard handle to a tower, and position the cable to shoulder height.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Facing forward, press the cable away from your chest. You core should be tight and engaged.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'Repeat to failure.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 9, 'Then, reposition and repeat the same series of movements on the opposite side.' FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'pallof-press-with-rotation' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'pallof-press-with-rotation' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'pallof-press-with-rotation' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'pallof-press-with-rotation' AND b.slug = 'triceps';
