INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'pallof-press-with-rotation';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('palms-down-dumbbell-wrist-curl-over-a-bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start out by placing two dumbbells on one side of a flat bench.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Kneel down on both of your knees so that your body is facing the flat bench.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Start out by curling your wrist upwards and exhaling.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Slowly lower your wrists back down to the starting position while inhaling.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'palms-down-dumbbell-wrist-curl-over-a-bench';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'palms-down-dumbbell-wrist-curl-over-a-bench' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'palms-down-dumbbell-wrist-curl-over-a-bench' AND q.slug = 'dumbbell';
