INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('parallel-bar-dip', 'Parallel Bar Dip', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Parallel_Bar_Dip', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.' FROM exercise WHERE slug = 'parallel-bar-dip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.' FROM exercise WHERE slug = 'parallel-bar-dip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Reverse the motion by extending the elbow, pushing yourself back up into the starting position.' FROM exercise WHERE slug = 'parallel-bar-dip';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the desired number of repetitions.' FROM exercise WHERE slug = 'parallel-bar-dip';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'parallel-bar-dip' AND b.slug = 'triceps';
