INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('plyo-kettlebell-pushups', 'Plyo Kettlebell Pushups', 'strength', 'push', 'compound', 'expert', 30, 90, 'free-exercise-db', 'Plyo_Kettlebell_Pushups', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.' FROM exercise WHERE slug = 'plyo-kettlebell-pushups';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by lowering yourself as low as you can, keeping your back straight.' FROM exercise WHERE slug = 'plyo-kettlebell-pushups';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.' FROM exercise WHERE slug = 'plyo-kettlebell-pushups';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'plyo-kettlebell-pushups' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'plyo-kettlebell-pushups' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'plyo-kettlebell-pushups' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'plyo-kettlebell-pushups' AND q.slug = 'kettlebells';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'plyo-kettlebell-pushups';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'plyo-kettlebell-pushups';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('plyo-push-up', 'Plyo Push-up', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Plyo_Push-up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Move into a prone position on the floor, supporting your weight on your hands and toes.' FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.' FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Descend by flexing at the elbow, lowering your chest towards the ground.' FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.' FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Return to the starting position and repeat the exercise.' FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'For added difficulty, add claps into the movement while you are air borne.' FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'plyo-push-up' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'plyo-push-up' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'plyo-push-up' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'plyo-push-up' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'plyo-push-up';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('posterior-tibialis-stretch', 'Posterior Tibialis Stretch', 'stretching', 'static', NULL, 'intermediate', 0, 15, 'free-exercise-db', 'Posterior_Tibialis_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.' FROM exercise WHERE slug = 'posterior-tibialis-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.' FROM exercise WHERE slug = 'posterior-tibialis-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'posterior-tibialis-stretch' AND b.slug = 'calves';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'posterior-tibialis-stretch' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'posterior-tibialis-stretch';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('power-clean', 'Power Clean', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Power_Clean', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Place the bar about 1 inch in front of your shins and over the balls of your feet.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'As the bar raises keep it as close to the shins as possible.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 9, 'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 10, 'Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 11, 'Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 12, 'Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 13, 'When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 14, 'As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 15, 'Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 16, 'After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 17, 'Simultaneously, flex the hips and knees into a quarter squat position.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 18, 'Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 19, 'Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 20, 'Stand up by extending the hips and knees to a fully erect position.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 21, 'Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 22, 'Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 23, 'Squat down with the elbows fully extended until the bar touches the floor.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 24, 'Start over at Phase 1 and repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'power-clean';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'calves';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'forearms';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'lower-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'middle-back';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-clean' AND b.slug = 'traps';
