INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('power-stairs', 'Power Stairs', 'strongman', 'pull', 'compound', 'intermediate', 60, 120, 'free-exercise-db', 'Power_Stairs', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.' FROM exercise WHERE slug = 'power-stairs';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.' FROM exercise WHERE slug = 'power-stairs';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair.' FROM exercise WHERE slug = 'power-stairs';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.' FROM exercise WHERE slug = 'power-stairs';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'power-stairs' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'power-stairs' AND b.slug = 'adductors';
