INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('prone-manual-hamstring', 'Prone Manual Hamstring', 'strength', 'static', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Prone_Manual_Hamstring', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.' FROM exercise WHERE slug = 'prone-manual-hamstring';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.' FROM exercise WHERE slug = 'prone-manual-hamstring';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.' FROM exercise WHERE slug = 'prone-manual-hamstring';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'prone-manual-hamstring' AND b.slug = 'hamstrings';
