INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('prowler-sprint', 'Prowler Sprint', 'cardio', 'push', 'compound', 'beginner', 15, 60, 'free-exercise-db', 'Prowler_Sprint', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.' FROM exercise WHERE slug = 'prowler-sprint';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.' FROM exercise WHERE slug = 'prowler-sprint';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.' FROM exercise WHERE slug = 'prowler-sprint';
