INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('push-ups-close-triceps-position', 'Push-Ups - Close Triceps Position', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Push-Ups_-_Close_Triceps_Position', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.' FROM exercise WHERE slug = 'push-ups-close-triceps-position';
