INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.' FROM exercise WHERE slug = 'push-ups-with-feet-elevated';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower yourself until your chest almost touches the floor as you inhale.' FROM exercise WHERE slug = 'push-ups-with-feet-elevated';
