INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.' FROM exercise WHERE slug = 'push-ups-with-feet-elevated';
