INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('push-press-behind-the-neck', 'Push Press - Behind the Neck', 'olympic_weightlifting', 'push', 'compound', 'intermediate', 60, 120, 'free-exercise-db', 'Push_Press_-_Behind_the_Neck', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.' FROM exercise WHERE slug = 'push-press-behind-the-neck';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Using the momentum generated, finish pressing the weight overhead be extending through the arms.' FROM exercise WHERE slug = 'push-press-behind-the-neck';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Return to the starting position, using your legs to absorb the impact.' FROM exercise WHERE slug = 'push-press-behind-the-neck';
