INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Get into pushup position on the toes with your hands just outside of shoulder width.' FROM exercise WHERE slug = 'push-up-to-side-plank';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.' FROM exercise WHERE slug = 'push-up-to-side-plank';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.' FROM exercise WHERE slug = 'push-up-to-side-plank';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Lower the arm back to the floor for another pushup and then twist to the other side.' FROM exercise WHERE slug = 'push-up-to-side-plank';
