INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'rack-pull-with-bands';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('rack-pulls', 'Rack Pulls', 'powerlifting', 'pull', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Rack_Pulls', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.' FROM exercise WHERE slug = 'rack-pulls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.' FROM exercise WHERE slug = 'rack-pulls';
