INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('return-push-from-stance', 'Return Push from Stance', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Return_Push_from_Stance', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'You will need a partner for this drill.' FROM exercise WHERE slug = 'return-push-from-stance';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin in an athletic 2 or 3 point stance.' FROM exercise WHERE slug = 'return-push-from-stance';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'At the signal, move into a position to receive the pass from your partner.' FROM exercise WHERE slug = 'return-push-from-stance';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Catch the medicine ball with both hands and immediately throw it back to your partner.' FROM exercise WHERE slug = 'return-push-from-stance';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'You can modify this drill by running different routes.' FROM exercise WHERE slug = 'return-push-from-stance';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'return-push-from-stance' AND b.slug = 'shoulders';
