INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'reverse-barbell-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('reverse-barbell-preacher-curls', 'Reverse Barbell Preacher Curls', 'strength', 'pull', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Reverse_Barbell_Preacher_Curls', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grab an EZ-bar using a shoulder width and palms down (pronated) grip.' FROM exercise WHERE slug = 'reverse-barbell-preacher-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.' FROM exercise WHERE slug = 'reverse-barbell-preacher-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.' FROM exercise WHERE slug = 'reverse-barbell-preacher-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.' FROM exercise WHERE slug = 'reverse-barbell-preacher-curls';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'reverse-barbell-preacher-curls';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'reverse-barbell-preacher-curls' AND b.slug = 'biceps';
