INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'reverse-barbell-preacher-curls' AND q.slug = 'e-z-curl-bar';
