INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('round-the-world-shoulder-stretch', 'Round The World Shoulder Stretch', 'stretching', 'static', NULL, 'beginner', 0, 15, 'free-exercise-db', 'Round_The_World_Shoulder_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand up straight with your legs together, holding a bodybar or broomstick.' FROM exercise WHERE slug = 'round-the-world-shoulder-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.' FROM exercise WHERE slug = 'round-the-world-shoulder-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further.' FROM exercise WHERE slug = 'round-the-world-shoulder-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'round-the-world-shoulder-stretch' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'round-the-world-shoulder-stretch' AND b.slug = 'biceps';
