INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'seated-dumbbell-inner-biceps-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('seated-dumbbell-palms-down-wrist-curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Seated_Dumbbell_Palms-Down_Wrist_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start out by placing two dumbbells on the floor in front of a flat bench.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Start out by curling your wrist upwards and exhaling.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'When finished, simply lower the dumbbells to the floor.' FROM exercise WHERE slug = 'seated-dumbbell-palms-down-wrist-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'seated-dumbbell-palms-down-wrist-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'seated-dumbbell-palms-down-wrist-curl' AND q.slug = 'dumbbell';
