INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('seated-dumbbell-press', 'Seated Dumbbell Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Seated_Dumbbell_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.' FROM exercise WHERE slug = 'seated-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.' FROM exercise WHERE slug = 'seated-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.' FROM exercise WHERE slug = 'seated-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'As you exhale, push the dumbbells up until they touch at the top.' FROM exercise WHERE slug = 'seated-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After a second pause, slowly come down back to the starting position as you inhale.' FROM exercise WHERE slug = 'seated-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'seated-dumbbell-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'seated-dumbbell-press' AND b.slug = 'shoulders';
