INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.' FROM exercise WHERE slug = 'seated-hamstring';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.' FROM exercise WHERE slug = 'seated-hamstring';
