INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('seated-hamstring-and-calf-stretch', 'Seated Hamstring and Calf Stretch', 'stretching', 'static', NULL, 'intermediate', 0, 15, 'free-exercise-db', 'Seated_Hamstring_and_Calf_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.' FROM exercise WHERE slug = 'seated-hamstring-and-calf-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.' FROM exercise WHERE slug = 'seated-hamstring-and-calf-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'seated-hamstring-and-calf-stretch' AND b.slug = 'hamstrings';
