INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('seated-two-arm-palms-up-low-pulley-wrist-curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now hold the handle with both hands, palms up, using a shoulder-width grip.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Lower the bar as far as possible, while inhaling and keeping a tight grip.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'After a second contraction at the top go back to the starting position as you inhale.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 9, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('see-saw-press-alternating-side-press', 'See-Saw Press (Alternating Side Press)', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'See-Saw_Press_Alternating_Side_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grab a dumbbell with each hand and stand up erect.' FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.' FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.' FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.' FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'see-saw-press-alternating-side-press' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'see-saw-press-alternating-side-press' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'see-saw-press-alternating-side-press' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'see-saw-press-alternating-side-press' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'see-saw-press-alternating-side-press';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('shotgun-row', 'Shotgun Row', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Shotgun_Row', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Attach a single handle to a low cable.' FROM exercise WHERE slug = 'shotgun-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.' FROM exercise WHERE slug = 'shotgun-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.' FROM exercise WHERE slug = 'shotgun-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After a brief pause, return to the starting position.' FROM exercise WHERE slug = 'shotgun-row';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'shotgun-row' AND b.slug = 'lats';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'shotgun-row' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'shotgun-row' AND b.slug = 'middle-back';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'shotgun-row' AND q.slug = 'cable';
