INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Reach your left arm across your body and hold it straight.' FROM exercise WHERE slug = 'shoulder-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'shoulder-stretch' AND b.slug = 'shoulders';
