INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('side-lying-floor-stretch', 'Side-Lying Floor Stretch', 'stretching', 'static', NULL, 'beginner', 0, 15, 'free-exercise-db', 'Side-Lying_Floor_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).' FROM exercise WHERE slug = 'side-lying-floor-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.' FROM exercise WHERE slug = 'side-lying-floor-stretch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'side-lying-floor-stretch' AND b.slug = 'lats';
