INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('side-hop-sprint', 'Side Hop-Sprint', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Side_Hop-Sprint', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand to the side of a cone or hurdle.' FROM exercise WHERE slug = 'side-hop-sprint';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.' FROM exercise WHERE slug = 'side-hop-sprint';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.' FROM exercise WHERE slug = 'side-hop-sprint';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'side-hop-sprint' AND b.slug = 'quadriceps';
