INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start with your shoulders relaxed, gently tilt your head towards your shoulder.' FROM exercise WHERE slug = 'side-neck-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Assist stretch with a gentle pull on the side of the head.' FROM exercise WHERE slug = 'side-neck-stretch';
