INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('side-to-side-chins', 'Side To Side Chins', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Side_To_Side_Chins', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grab the pull-up bar with the palms facing forward using a wide grip.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After a second of contraction, inhale as you go back to the starting position.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'After a second of contraction, inhale as you go back to the starting position.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side.' FROM exercise WHERE slug = 'side-to-side-chins';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'side-to-side-chins' AND b.slug = 'lats';
