INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('side-wrist-pull', 'Side Wrist Pull', 'stretching', 'static', 'isolation', 'beginner', 0, 15, 'free-exercise-db', 'Side_Wrist_Pull', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.' FROM exercise WHERE slug = 'side-wrist-pull';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides.' FROM exercise WHERE slug = 'side-wrist-pull';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'side-wrist-pull' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'side-wrist-pull' AND b.slug = 'forearms';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'side-wrist-pull' AND b.slug = 'lats';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'side-wrist-pull';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('side-to-side-box-shuffle', 'Side to Side Box Shuffle', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Side_to_Side_Box_Shuffle', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand to one side of the box with your left foot resting on the middle of it.' FROM exercise WHERE slug = 'side-to-side-box-shuffle';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.' FROM exercise WHERE slug = 'side-to-side-box-shuffle';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Continue shuffling back and forth across the box.' FROM exercise WHERE slug = 'side-to-side-box-shuffle';
