INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('single-arm-cable-crossover', 'Single-Arm Cable Crossover', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Single-Arm_Cable_Crossover', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.' FROM exercise WHERE slug = 'single-arm-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.' FROM exercise WHERE slug = 'single-arm-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.' FROM exercise WHERE slug = 'single-arm-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return your arm back to the starting position by pulling your hand back to the midline of the body.' FROM exercise WHERE slug = 'single-arm-cable-crossover';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.' FROM exercise WHERE slug = 'single-arm-cable-crossover';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'single-arm-cable-crossover' AND b.slug = 'chest';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'single-arm-cable-crossover' AND q.slug = 'cable';
