INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('single-arm-linear-jammer', 'Single-Arm Linear Jammer', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Single-Arm_Linear_Jammer', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.' FROM exercise WHERE slug = 'single-arm-linear-jammer';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.' FROM exercise WHERE slug = 'single-arm-linear-jammer';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.' FROM exercise WHERE slug = 'single-arm-linear-jammer';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return to the starting position.' FROM exercise WHERE slug = 'single-arm-linear-jammer';
