INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('single-arm-push-up', 'Single-Arm Push-Up', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Single-Arm_Push-Up', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.' FROM exercise WHERE slug = 'single-arm-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Maintain good posture, and place your free hand behind your back. This will be your starting position.' FROM exercise WHERE slug = 'single-arm-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower yourself by allowing the elbow to flex until you touch the ground.' FROM exercise WHERE slug = 'single-arm-push-up';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Descend slowly, and reverse direction be extending the arm to return to the starting position.' FROM exercise WHERE slug = 'single-arm-push-up';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'single-arm-push-up' AND b.slug = 'chest';
