INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('single-cone-sprint-drill', 'Single-Cone Sprint Drill', 'plyometrics', 'push', NULL, 'beginner', 30, 60, 'free-exercise-db', 'Single-Cone_Sprint_Drill', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.' FROM exercise WHERE slug = 'single-cone-sprint-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.' FROM exercise WHERE slug = 'single-cone-sprint-drill';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Rest after three trips around the cone.' FROM exercise WHERE slug = 'single-cone-sprint-drill';
