INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a box in a rack. Secure a band or rope in place above the box.' FROM exercise WHERE slug = 'single-leg-high-box-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance' FROM exercise WHERE slug = 'single-leg-high-box-squat';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, '. Continue stepping up and down on the same leg before switching to the opposite side.' FROM exercise WHERE slug = 'single-leg-high-box-squat';
