INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('single-leg-lateral-hop', 'Single-Leg Lateral Hop', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Single-Leg_Lateral_Hop', 'published');
