INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('sled-overhead-triceps-extension', 'Sled Overhead Triceps Extension', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Sled_Overhead_Triceps_Extension', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.' FROM exercise WHERE slug = 'sled-overhead-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.' FROM exercise WHERE slug = 'sled-overhead-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.' FROM exercise WHERE slug = 'sled-overhead-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability.' FROM exercise WHERE slug = 'sled-overhead-triceps-extension';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'sled-overhead-triceps-extension' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'sled-overhead-triceps-extension' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'sled-overhead-triceps-extension';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('sled-push', 'Sled Push', 'strongman', 'push', 'compound', 'beginner', 60, 120, 'free-exercise-db', 'Sled_Push', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Load your pushing sled with the desired weight.' FROM exercise WHERE slug = 'sled-push';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.' FROM exercise WHERE slug = 'sled-push';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'sled-push' AND b.slug = 'quadriceps';
