INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('smith-machine-decline-press', 'Smith Machine Decline Press', 'strength', NULL, 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Smith_Machine_Decline_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.' FROM exercise WHERE slug = 'smith-machine-decline-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.' FROM exercise WHERE slug = 'smith-machine-decline-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin the movement by flexing your arms, lowering the bar to your chest.' FROM exercise WHERE slug = 'smith-machine-decline-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pause briefly, and then extend your arms to push the weight back to the starting position.' FROM exercise WHERE slug = 'smith-machine-decline-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'After completing the desired number of repetitions, rotate the bar to rack the weight.' FROM exercise WHERE slug = 'smith-machine-decline-press';
