INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('split-jump', 'Split Jump', 'plyometrics', 'push', 'compound', 'beginner', 30, 60, 'free-exercise-db', 'Split_Jump', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.' FROM exercise WHERE slug = 'split-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Ensure that the front knee is over the midline of the foot.' FROM exercise WHERE slug = 'split-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Extending through both legs, jump as high as possible, swinging your arms to gain lift.' FROM exercise WHERE slug = 'split-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'As you jump, bring your feet together, and move them back to their initial positions as you land.' FROM exercise WHERE slug = 'split-jump';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Absorb the impact by reverting back to the starting position.' FROM exercise WHERE slug = 'split-jump';
