INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('split-squat-with-dumbbells', 'Split Squat with Dumbbells', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Split_Squat_with_Dumbbells', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position yourself into a staggered stance with the rear foot elevated and front foot forward.' FROM exercise WHERE slug = 'split-squat-with-dumbbells';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.' FROM exercise WHERE slug = 'split-squat-with-dumbbells';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.' FROM exercise WHERE slug = 'split-squat-with-dumbbells';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.' FROM exercise WHERE slug = 'split-squat-with-dumbbells';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'split-squat-with-dumbbells' AND b.slug = 'quadriceps';
