INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('squat-with-plate-movers', 'Squat with Plate Movers', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Squat_with_Plate_Movers', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'At the top of the movement, side step, bringing your feet together on the opposite side of the plate.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.' FROM exercise WHERE slug = 'squat-with-plate-movers';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'Place your inside foot on the weight plate, adopting a wide stance for the next repetition.' FROM exercise WHERE slug = 'squat-with-plate-movers';
