INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-bradford-press', 'Standing Bradford Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Bradford_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.' FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.' FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower the bar down to the back of the head until your elbow forms a right angle.' FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Lift the bar back over your head by extending the elbows' FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Lower the bar down to the starting position.' FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Alternate in this manner until you complete the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-bradford-press' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-bradford-press' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-bradford-press' AND q.slug = 'barbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-bradford-press';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-cable-chest-press', 'Standing Cable Chest Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Cable_Chest_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.' FROM exercise WHERE slug = 'standing-cable-chest-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.' FROM exercise WHERE slug = 'standing-cable-chest-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.' FROM exercise WHERE slug = 'standing-cable-chest-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pause at the top of the motion, and return to the starting position.' FROM exercise WHERE slug = 'standing-cable-chest-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-chest-press' AND b.slug = 'chest';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-chest-press' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-chest-press' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-cable-chest-press' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-cable-chest-press';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-cable-chest-press';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-cable-lift', 'Standing Cable Lift', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Cable_Lift', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Connect a standard handle on a tower, and move the cable to the lowest pulley position.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat to failure.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'Then, reposition and repeat the same series of movements on the opposite side.' FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-lift' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-lift' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-cable-lift' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-cable-lift';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-cable-wood-chop', 'Standing Cable Wood Chop', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Cable_Wood_Chop', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Connect a standard handle to a tower, and move the cable to the highest pulley position.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'In one motion, pull the handle down and across your body to your front knee while rotating your torso.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Repeat to failure.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 8, 'Then, reposition and repeat the same series of movements on the opposite side.' FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-wood-chop' AND b.slug = 'abdominals';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-cable-wood-chop' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-cable-wood-chop' AND q.slug = 'cable';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-cable-wood-chop';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-calf-raises', 'Standing Calf Raises', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Calf_Raises', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Adjust the padded lever of the calf raise machine to fit your height.' FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.' FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.' FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.' FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-calf-raises' AND b.slug = 'calves';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-calf-raises' AND q.slug = 'machine';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-calf-raises';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-concentration-curl', 'Standing Concentration Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Concentration_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.' FROM exercise WHERE slug = 'standing-concentration-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.' FROM exercise WHERE slug = 'standing-concentration-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower the dumbbell back to the starting position.' FROM exercise WHERE slug = 'standing-concentration-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat the movement for the prescribed amount of repetitions.' FROM exercise WHERE slug = 'standing-concentration-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-concentration-curl' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-concentration-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-concentration-curl' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-concentration-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-concentration-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-dumbbell-calf-raise', 'Standing Dumbbell Calf Raise', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Standing_Dumbbell_Calf_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.' FROM exercise WHERE slug = 'standing-dumbbell-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.' FROM exercise WHERE slug = 'standing-dumbbell-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you inhale, go back to the starting position by slowly lowering the heels.' FROM exercise WHERE slug = 'standing-dumbbell-calf-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of times.' FROM exercise WHERE slug = 'standing-dumbbell-calf-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-dumbbell-calf-raise' AND b.slug = 'calves';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-dumbbell-calf-raise' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-dumbbell-calf-raise';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-dumbbell-calf-raise';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-dumbbell-press', 'Standing Dumbbell Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Dumbbell_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.' FROM exercise WHERE slug = 'standing-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.' FROM exercise WHERE slug = 'standing-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Pause, and slowly return the weight to the starting position.' FROM exercise WHERE slug = 'standing-dumbbell-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-dumbbell-press' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-dumbbell-press' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-dumbbell-press' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-dumbbell-press';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-dumbbell-press';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-dumbbell-reverse-curl', 'Standing Dumbbell Reverse Curl', 'strength', 'pull', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Standing_Dumbbell_Reverse_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.' FROM exercise WHERE slug = 'standing-dumbbell-reverse-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.' FROM exercise WHERE slug = 'standing-dumbbell-reverse-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly begin to bring the dumbbells back to starting position as your breathe in.' FROM exercise WHERE slug = 'standing-dumbbell-reverse-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-dumbbell-reverse-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-dumbbell-reverse-curl' AND b.slug = 'biceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-dumbbell-reverse-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-dumbbell-reverse-curl' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'standing-dumbbell-reverse-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-dumbbell-reverse-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-dumbbell-straight-arm-front-delt-raise-above-head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'strength', 'push', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Hold the dumbbells in front of your thighs, palms facing your thighs.' FROM exercise WHERE slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.' FROM exercise WHERE slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.' FROM exercise WHERE slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Slowly return to the starting position using the same path as you inhale.' FROM exercise WHERE slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-dumbbell-straight-arm-front-delt-raise-above-head' AND q.slug = 'dumbbell';
