INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'standing-military-press';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-olympic-plate-hand-squeeze', 'Standing Olympic Plate Hand Squeeze', 'strength', 'static', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Olympic_Plate_Hand_Squeeze', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.' FROM exercise WHERE slug = 'standing-olympic-plate-hand-squeeze';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.' FROM exercise WHERE slug = 'standing-olympic-plate-hand-squeeze';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Now raise the plates back to the starting position as you exhale by closing your hands.' FROM exercise WHERE slug = 'standing-olympic-plate-hand-squeeze';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Repeat for the recommended amount of repetitions prescribed in your program.' FROM exercise WHERE slug = 'standing-olympic-plate-hand-squeeze';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-olympic-plate-hand-squeeze' AND b.slug = 'forearms';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-olympic-plate-hand-squeeze' AND b.slug = 'biceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-olympic-plate-hand-squeeze' AND q.slug = 'other';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'duration', True FROM exercise WHERE slug = 'standing-olympic-plate-hand-squeeze';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-one-arm-cable-curl', 'Standing One-Arm Cable Curl', 'strength', 'pull', 'isolation', 'intermediate', 30, 90, 'free-exercise-db', 'Standing_One-Arm_Cable_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.' FROM exercise WHERE slug = 'standing-one-arm-cable-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.' FROM exercise WHERE slug = 'standing-one-arm-cable-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.' FROM exercise WHERE slug = 'standing-one-arm-cable-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.' FROM exercise WHERE slug = 'standing-one-arm-cable-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-one-arm-cable-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Switch arms while performing this exercise.' FROM exercise WHERE slug = 'standing-one-arm-cable-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-one-arm-cable-curl' AND b.slug = 'biceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-one-arm-cable-curl' AND q.slug = 'cable';
