INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-overhead-barbell-triceps-extension', 'Standing Overhead Barbell Triceps Extension', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Overhead_Barbell_Triceps_Extension', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.' FROM exercise WHERE slug = 'standing-overhead-barbell-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.' FROM exercise WHERE slug = 'standing-overhead-barbell-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.' FROM exercise WHERE slug = 'standing-overhead-barbell-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.' FROM exercise WHERE slug = 'standing-overhead-barbell-triceps-extension';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-overhead-barbell-triceps-extension';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-overhead-barbell-triceps-extension' AND b.slug = 'triceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-overhead-barbell-triceps-extension' AND b.slug = 'shoulders';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-overhead-barbell-triceps-extension' AND q.slug = 'barbell';
