INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-palm-in-one-arm-dumbbell-press', 'Standing Palm-In One-Arm Dumbbell Press', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Palm-In_One-Arm_Dumbbell_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Slowly lift the dumbbell up until your arm is fully extended. This the starting position.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'While inhaling lower the weight down until your arm is at a 90 degree angle again.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 7, 'Switch arms and repeat the exercise.' FROM exercise WHERE slug = 'standing-palm-in-one-arm-dumbbell-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-palm-in-one-arm-dumbbell-press' AND b.slug = 'shoulders';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'standing-palm-in-one-arm-dumbbell-press' AND b.slug = 'triceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-palm-in-one-arm-dumbbell-press' AND q.slug = 'dumbbell';
