INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-palms-up-barbell-behind-the-back-wrist-curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.' FROM exercise WHERE slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.' FROM exercise WHERE slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.' FROM exercise WHERE slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.' FROM exercise WHERE slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you.' FROM exercise WHERE slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl' AND b.slug = 'forearms';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'standing-palms-up-barbell-behind-the-back-wrist-curl' AND q.slug = 'barbell';
