INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Bend your knees slightly to keep them soft and springy.' FROM exercise WHERE slug = 'standing-pelvic-tilt';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.' FROM exercise WHERE slug = 'standing-pelvic-tilt';
