INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-rope-crunch', 'Standing Rope Crunch', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Standing_Rope_Crunch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Attach a rope to a high pulley and select an appropriate weight.' FROM exercise WHERE slug = 'standing-rope-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.' FROM exercise WHERE slug = 'standing-rope-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Perform the movement by flexing the spine, crunching the weight down as far as you can.' FROM exercise WHERE slug = 'standing-rope-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Hold the peak contraction for a moment before returning to the starting position.' FROM exercise WHERE slug = 'standing-rope-crunch';
