INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('standing-soleus-and-achilles-stretch', 'Standing Soleus And Achilles Stretch', 'stretching', 'static', 'isolation', 'beginner', 0, 15, 'free-exercise-db', 'Standing_Soleus_And_Achilles_Stretch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand with your feet hip-distance apart, one foot slightly in front of the other.' FROM exercise WHERE slug = 'standing-soleus-and-achilles-stretch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Bend both knees, keeping your back heel on the floor. Switch sides.' FROM exercise WHERE slug = 'standing-soleus-and-achilles-stretch';
