INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('step-up-with-knee-raise', 'Step-up with Knee Raise', 'strength', 'push', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Step-up_with_Knee_Raise', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.' FROM exercise WHERE slug = 'step-up-with-knee-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.' FROM exercise WHERE slug = 'step-up-with-knee-raise';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.' FROM exercise WHERE slug = 'step-up-with-knee-raise';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'step-up-with-knee-raise' AND b.slug = 'glutes';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'step-up-with-knee-raise' AND b.slug = 'hamstrings';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'secondary' FROM exercise e, body_part b WHERE e.slug = 'step-up-with-knee-raise' AND b.slug = 'quadriceps';
