INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('stiff-legged-dumbbell-deadlift', 'Stiff-Legged Dumbbell Deadlift', 'strength', 'pull', 'compound', 'beginner', 30, 90, 'free-exercise-db', 'Stiff-Legged_Dumbbell_Deadlift', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grasp a couple of dumbbells holding them by your side at arm''s length.' FROM exercise WHERE slug = 'stiff-legged-dumbbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.' FROM exercise WHERE slug = 'stiff-legged-dumbbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement' FROM exercise WHERE slug = 'stiff-legged-dumbbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.' FROM exercise WHERE slug = 'stiff-legged-dumbbell-deadlift';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'stiff-legged-dumbbell-deadlift';
