INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.' FROM exercise WHERE slug = 'sumo-deadlift-with-bands';
