INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('sumo-deadlift-with-chains', 'Sumo Deadlift with Chains', 'powerlifting', 'pull', 'compound', 'intermediate', 60, 150, 'free-exercise-db', 'Sumo_Deadlift_with_Chains', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.' FROM exercise WHERE slug = 'sumo-deadlift-with-chains';
