INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('triceps-pushdown-rope-attachment', 'Triceps Pushdown - Rope Attachment', 'strength', 'push', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Triceps_Pushdown_-_Rope_Attachment', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).' FROM exercise WHERE slug = 'triceps-pushdown-rope-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.' FROM exercise WHERE slug = 'triceps-pushdown-rope-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.' FROM exercise WHERE slug = 'triceps-pushdown-rope-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.' FROM exercise WHERE slug = 'triceps-pushdown-rope-attachment';
