INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.' FROM exercise WHERE slug = 'triceps-pushdown-v-bar-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.' FROM exercise WHERE slug = 'triceps-pushdown-v-bar-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.' FROM exercise WHERE slug = 'triceps-pushdown-v-bar-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.' FROM exercise WHERE slug = 'triceps-pushdown-v-bar-attachment';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'triceps-pushdown-v-bar-attachment';
