INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('tuck-crunch', 'Tuck Crunch', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Tuck_Crunch', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.' FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.' FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.' FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.' FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 5, 'Slowly begin to lower your torso back down to the starting position while inhaling.' FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 6, 'Repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'tuck-crunch' AND b.slug = 'abdominals';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'tuck-crunch' AND q.slug = 'body-only';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'tuck-crunch';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('two-arm-dumbbell-preacher-curl', 'Two-Arm Dumbbell Preacher Curl', 'strength', 'pull', 'isolation', 'beginner', 30, 90, 'free-exercise-db', 'Two-Arm_Dumbbell_Preacher_Curl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.' FROM exercise WHERE slug = 'two-arm-dumbbell-preacher-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.' FROM exercise WHERE slug = 'two-arm-dumbbell-preacher-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.' FROM exercise WHERE slug = 'two-arm-dumbbell-preacher-curl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.' FROM exercise WHERE slug = 'two-arm-dumbbell-preacher-curl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'two-arm-dumbbell-preacher-curl' AND b.slug = 'biceps';
INSERT INTO exercise_equipment (exercise_id, equipment_id, is_required) SELECT e.id, q.id, true FROM exercise e, equipment q WHERE e.slug = 'two-arm-dumbbell-preacher-curl' AND q.slug = 'dumbbell';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'reps', True FROM exercise WHERE slug = 'two-arm-dumbbell-preacher-curl';
INSERT INTO exercise_metric (exercise_id, metric, is_primary) SELECT id, 'weight', False FROM exercise WHERE slug = 'two-arm-dumbbell-preacher-curl';
INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('two-arm-kettlebell-clean', 'Two-Arm Kettlebell Clean', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Two-Arm_Kettlebell_Clean', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.' FROM exercise WHERE slug = 'two-arm-kettlebell-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.' FROM exercise WHERE slug = 'two-arm-kettlebell-clean';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Lower the kettlebells back to the starting position and repeat.' FROM exercise WHERE slug = 'two-arm-kettlebell-clean';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'two-arm-kettlebell-clean' AND b.slug = 'shoulders';
