INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('two-arm-kettlebell-jerk', 'Two-Arm Kettlebell Jerk', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Two-Arm_Kettlebell_Jerk', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.' FROM exercise WHERE slug = 'two-arm-kettlebell-jerk';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'two-arm-kettlebell-jerk' AND b.slug = 'shoulders';
