INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('two-arm-kettlebell-military-press', 'Two-Arm Kettlebell Military Press', 'strength', 'push', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Two-Arm_Kettlebell_Military_Press', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.' FROM exercise WHERE slug = 'two-arm-kettlebell-military-press';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.' FROM exercise WHERE slug = 'two-arm-kettlebell-military-press';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'two-arm-kettlebell-military-press' AND b.slug = 'shoulders';
