INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('two-arm-kettlebell-row', 'Two-Arm Kettlebell Row', 'strength', 'pull', 'compound', 'intermediate', 30, 90, 'free-exercise-db', 'Two-Arm_Kettlebell_Row', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.' FROM exercise WHERE slug = 'two-arm-kettlebell-row';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.' FROM exercise WHERE slug = 'two-arm-kettlebell-row';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'two-arm-kettlebell-row' AND b.slug = 'middle-back';
