INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('squat-thrust-half-burpee', 'Squat Thrust (Half Burpee)', 'hiit', 'push', 'compound', 'beginner', 15, 30, 'original', 'Squat_Thrust', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Stand with feet shoulder-width apart and arms by your sides.' FROM exercise WHERE slug = 'squat-thrust-half-burpee';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Squat down and place your hands on the floor in front of your feet.' FROM exercise WHERE slug = 'squat-thrust-half-burpee';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Jump both feet back into a high plank position.' FROM exercise WHERE slug = 'squat-thrust-half-burpee';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Immediately jump your feet back to your hands.' FROM exercise WHERE slug = 'squat-thrust-half-burpee';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Stand up tall to finish the rep. No push-up and no jump — keep the pace brisk.' FROM exercise WHERE slug = 'squat-thrust-half-burpee';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'squat-thrust-half-burpee' AND b.slug = 'quadriceps';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'squat-thrust-half-burpee' AND b.slug = 'abdominals';
