INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('sprawl', 'Sprawl', 'hiit', 'push', 'compound', 'intermediate', 15, 45, 'original', 'Sprawl', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Stand in an athletic stance with knees slightly bent.' FROM exercise WHERE slug = 'sprawl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Drop your hands to the floor and shoot your legs back, letting your hips sink toward the ground while your chest stays off the floor.' FROM exercise WHERE slug = 'sprawl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Keep your head up and back flat at the bottom.' FROM exercise WHERE slug = 'sprawl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Snap your feet back underneath your hips in one explosive motion.' FROM exercise WHERE slug = 'sprawl';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Return to standing and repeat.' FROM exercise WHERE slug = 'sprawl';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'sprawl' AND b.slug = 'quadriceps';
