INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('jumping-jacks', 'Jumping Jacks', 'cardio', 'push', 'compound', 'beginner', 15, 20, 'original', 'Jumping_Jacks', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Stand tall with feet together and arms at your sides.' FROM exercise WHERE slug = 'jumping-jacks';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Jump your feet out to just wider than shoulder width while swinging your arms overhead.' FROM exercise WHERE slug = 'jumping-jacks';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Jump your feet back together while bringing your arms back to your sides.' FROM exercise WHERE slug = 'jumping-jacks';
