INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('half-moon-pose-with-hands-to-feet-ardha-chandrasana-with-pada-hastasana', 'Half Moon Pose with Hands to Feet (Ardha Chandrasana with Pada Hastasana)', 'yoga', 'static', 'compound', 'intermediate', 0, 15, 'original', 'Bikram_02_Half_Moon_Hands_To_Feet', 'published');
