INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Press your hips to the left and bend your whole torso to the right in one unbroken line, arms glued to your ears. Hold and breathe.' FROM exercise WHERE slug = 'half-moon-pose-with-hands-to-feet-ardha-chandrasana-with-pada-hastasana';
