INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Return to centre, then hinge back from the hips into a gentle standing backbend, pushing your hips forward.' FROM exercise WHERE slug = 'half-moon-pose-with-hands-to-feet-ardha-chandrasana-with-pada-hastasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Come up, fold forward and take hold of your heels from behind, drawing your chest to your thighs with elbows behind your calves.' FROM exercise WHERE slug = 'half-moon-pose-with-hands-to-feet-ardha-chandrasana-with-pada-hastasana';
