INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('fixed-firm-pose-supta-vajrasana', 'Fixed Firm Pose (Supta Vajrasana)', 'yoga', 'static', 'compound', 'intermediate', 0, 15, 'original', 'Bikram_20_Fixed_Firm_Pose', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Kneel with your knees together and sit your hips on the floor between your heels, feet hugging your hips.' FROM exercise WHERE slug = 'fixed-firm-pose-supta-vajrasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Walk your hands back behind you and lower onto your elbows, keeping both knees on the floor.' FROM exercise WHERE slug = 'fixed-firm-pose-supta-vajrasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'If comfortable, lower your back and shoulders all the way to the floor and reach your arms overhead, holding opposite elbows.' FROM exercise WHERE slug = 'fixed-firm-pose-supta-vajrasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Let the front of your thighs lengthen; breathe slowly into your belly.' FROM exercise WHERE slug = 'fixed-firm-pose-supta-vajrasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Come up the same way you went down — onto elbows first, never twisting.' FROM exercise WHERE slug = 'fixed-firm-pose-supta-vajrasana';
