INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Come up in one piece with arms still beside your ears.' FROM exercise WHERE slug = 'half-tortoise-pose-ardha-kurmasana';
