INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('head-to-knee-pose-with-stretching-pose-janushirasana-with-paschimotthanasana', 'Head to Knee Pose with Stretching Pose (Janushirasana with Paschimotthanasana)', 'yoga', 'static', 'compound', 'intermediate', 0, 15, 'original', 'Bikram_24_Head_To_Knee_With_Stretching', 'published');
