INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Turn your torso over the straight leg, grip your flexed right foot with both hands and bring your forehead toward your knee, bending the knee if needed.' FROM exercise WHERE slug = 'head-to-knee-pose-with-stretching-pose-janushirasana-with-paschimotthanasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Hold, breathe, then repeat on the other side.' FROM exercise WHERE slug = 'head-to-knee-pose-with-stretching-pose-janushirasana-with-paschimotthanasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'For the stretching stage, extend both legs together, grip your feet and fold your whole torso forward over your legs.' FROM exercise WHERE slug = 'head-to-knee-pose-with-stretching-pose-janushirasana-with-paschimotthanasana';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Pull gently with the arms while keeping the spine long; let the head release last.' FROM exercise WHERE slug = 'head-to-knee-pose-with-stretching-pose-janushirasana-with-paschimotthanasana';
