INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Kneel sitting on your heels with your spine tall and palms resting on your knees.' FROM exercise WHERE slug = 'blowing-in-firm-pose-kapalbhati-in-vajrasana';
