INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('jefferson-curl', 'Jefferson Curl', 'mobility', 'pull', 'compound', 'intermediate', 0, 30, 'original', 'Jefferson_Curl', 'published');
