INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Load a rucksack (bergen) to the prescribed weight, packed high and tight against your back, straps snug.' FROM exercise WHERE slug = 'loaded-march-tab';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 2, 'Wear broken-in boots or sturdy footwear and plan a measured route.' FROM exercise WHERE slug = 'loaded-march-tab';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'March at a brisk, sustainable pace — around 6 to 7 km/h on flat ground — driving through the full foot.' FROM exercise WHERE slug = 'loaded-march-tab';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stay tall under the load: chest up, shoulders back, core braced against the pack.' FROM exercise WHERE slug = 'loaded-march-tab';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Take shorter, quicker steps uphill and controlled steps downhill.' FROM exercise WHERE slug = 'loaded-march-tab';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Cover the prescribed distance or time; build weight and distance gradually week on week.' FROM exercise WHERE slug = 'loaded-march-tab';
