INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Lay a heavy sandbag or drag dummy (training standard is around 110 kg, scale to ability) on a smooth, flat surface.' FROM exercise WHERE slug = 'casualty-drag';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 2, 'Mark out a 20-metre course.' FROM exercise WHERE slug = 'casualty-drag';
