INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Sit into a low position with your chest up and arms locked long.' FROM exercise WHERE slug = 'casualty-drag';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Drive backward with powerful steps, leaning your bodyweight against the load.' FROM exercise WHERE slug = 'casualty-drag';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Keep your spine neutral and your steps short and fast until the full distance is covered.' FROM exercise WHERE slug = 'casualty-drag';
