INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('jerry-can-carry', 'Jerry Can Carry', 'strongman', 'static', 'compound', 'beginner', 60, 90, 'original', 'Jerry_Can_Carry', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Place a filled jerry can (or heavy dumbbell/kettlebell) beside each foot — the military standard is two 20 kg cans.' FROM exercise WHERE slug = 'jerry-can-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Deadlift both cans to standing with a flat back.' FROM exercise WHERE slug = 'jerry-can-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Walk the prescribed distance at a brisk, controlled pace, cans held at your sides.' FROM exercise WHERE slug = 'jerry-can-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Stay perfectly upright — no leaning, no swinging the cans.' FROM exercise WHERE slug = 'jerry-can-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Set the cans down with a flat back, rest as prescribed, and repeat.' FROM exercise WHERE slug = 'jerry-can-carry';
