INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('stretcher-carry', 'Stretcher Carry', 'strongman', 'static', 'compound', 'intermediate', 60, 120, 'original', 'Stretcher_Carry', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Load a stretcher, litter or long bar to the prescribed weight. Work with a partner of similar height when carrying as a pair.' FROM exercise WHERE slug = 'stretcher-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Squat down with a flat back and grip the handles at both ends.' FROM exercise WHERE slug = 'stretcher-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Stand together on a count, keeping the stretcher level.' FROM exercise WHERE slug = 'stretcher-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Walk the prescribed distance with short, synchronised steps, shoulders packed and core braced.' FROM exercise WHERE slug = 'stretcher-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Lower together with control. Swap ends or hands each interval to balance the load.' FROM exercise WHERE slug = 'stretcher-carry';
