INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('isometric-mid-thigh-pull', 'Isometric Mid-Thigh Pull', 'strength', 'pull', 'compound', 'beginner', 30, 120, 'original', 'Mid_Thigh_Pull', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Set a barbell in a power rack at mid-thigh height and pin it so it cannot move (or load it far beyond your maximum).' FROM exercise WHERE slug = 'isometric-mid-thigh-pull';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 2, 'Stand with the bar at mid-thigh, hands just outside your legs in an overhand grip.' FROM exercise WHERE slug = 'isometric-mid-thigh-pull';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Set a flat back, chest up, shoulders slightly over the bar — a strong deadlift lockout position.' FROM exercise WHERE slug = 'isometric-mid-thigh-pull';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Pull upward against the immovable bar as hard as possible for around 5 seconds.' FROM exercise WHERE slug = 'isometric-mid-thigh-pull';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Drive through your whole foot and keep your arms straight — the legs and hips produce the force.' FROM exercise WHERE slug = 'isometric-mid-thigh-pull';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Release gradually, never abruptly. Rest fully between efforts.' FROM exercise WHERE slug = 'isometric-mid-thigh-pull';
INSERT INTO exercise_body_part (exercise_id, body_part_id, role) SELECT e.id, b.id, 'primary' FROM exercise e, body_part b WHERE e.slug = 'isometric-mid-thigh-pull' AND b.slug = 'glutes';
