INSERT INTO exercise (slug, name, modality, force, mechanic, level, min_rest_seconds, default_rest_seconds, source, source_id, status) VALUES ('seated-medicine-ball-power-throw', 'Seated Medicine Ball Power Throw', 'plyometrics', 'push', 'compound', 'beginner', 30, 90, 'original', 'Seated_Medicine_Ball_Power_Throw', 'published');
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Sit on the floor with your back and head flat against a wall, legs extended in front of you.' FROM exercise WHERE slug = 'seated-medicine-ball-power-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 2, 'Hold a 4 kg medicine ball at your chest with both hands.' FROM exercise WHERE slug = 'seated-medicine-ball-power-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Keeping your back against the wall throughout, explosively press the ball up and out at roughly 45 degrees.' FROM exercise WHERE slug = 'seated-medicine-ball-power-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Throw as far as possible — the distance from the wall to first bounce is your score.' FROM exercise WHERE slug = 'seated-medicine-ball-power-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'No rocking or leaning forward: all the power comes from your chest, shoulders and arms.' FROM exercise WHERE slug = 'seated-medicine-ball-power-throw';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Take full rest between attempts and record your best.' FROM exercise WHERE slug = 'seated-medicine-ball-power-throw';
