INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'setup', 1, 'Work with a partner of similar size, or use a heavy sandbag. Practise the lift unloaded first.' FROM exercise WHERE slug = 'fireman-s-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 1, 'Squat and pull the partner''s arm across your shoulders, ducking your head under so their torso lies across your upper back.' FROM exercise WHERE slug = 'fireman-s-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 2, 'Wrap one arm behind their knee and grip their wrist with the same hand, locking the load to your shoulders.' FROM exercise WHERE slug = 'fireman-s-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 3, 'Stand by driving through your legs with a neutral spine.' FROM exercise WHERE slug = 'fireman-s-carry';
INSERT INTO exercise_instruction (exercise_id, phase, step_number, body) SELECT id, 'execution', 4, 'Walk the prescribed distance with short, stable steps, then lower them down with control.' FROM exercise WHERE slug = 'fireman-s-carry';
